window.COURSES=[{"id": "iv", "name": "투자론", "g": "iv", "d": "대학원 투자론 강의 목차(1~8장) + CAPM·효율적 시장. 시험 대비 계산 문제 포함", "units": [{"id": "iv1", "t": "투자론 입문", "ic": "入", "d": "투자의 정의, 위험과 수익, 차익거래", "cards": [{"h": "투자란", "p": "미래의 불확실한 기대수익을 위해 지금의 돈이나 자원을 유보하는 선택이에요. 기대수익률은 <b>시간에 대한 보상</b>과 <b>위험에 대한 보상</b>으로 이뤄져요.", "f": "기대수익률 = 시간에 대한 보상 + 위험에 대한 보상\n명목이자율 ≈ 실질이자율 + 예상인플레이션"}, {"h": "투자의 세 요소", "p": "<b>수익성 · 유동성(환금성) · 안정성</b>은 동시에 최대화할 수 없어요. 원금손실 가능성이 있으면 금융투자상품, 원금을 <b>초과</b>하는 손실이 가능하면 파생상품이에요."}, {"h": "투자 실행과정", "p": "<b>자본배분</b>(위험자산과 무위험자산 비율) → <b>자산배분</b>(주식·채권 등) → <b>종목선택</b> 순서예요. 지수를 따라가는 운용은 소극적 관리, 시장을 이기려는 운용은 적극적 관리예요."}, {"h": "위험–수익 상충", "p": "위험이 큰 자산은 투자자가 보유하도록 <b>더 높은 기대수익을 제시해야</b> 해요. \"위험이 크면 실제로 더 번다\"는 뜻이 아니에요. 기대값 20,000원짜리 동전 게임에 위험회피자가 19,000원만 낸다면 차이 1,000원이 위험프리미엄이에요."}, {"h": "차익거래와 일물일가", "p": "같은 위험·수익의 자산이 다른 가격이면 비싼 것을 팔고 싼 것을 사서 무위험이익을 얻어요. 이 거래가 가격을 같게 만들기 때문에 균형시장에는 차익거래 기회가 없어요(<b>무차익원리</b>). 파생상품 가격결정의 출발점이에요."}], "q": [{"k": "mc", "q": "기대수익률을 구성하는 두 가지는?", "o": ["시간에 대한 보상 + 위험에 대한 보상", "배당 + 시세차익", "이자 + 원금", "세금 + 수수료"], "e": ""}, {"k": "calc", "q": "앞면 10,000원, 뒷면 30,000원을 받는 동전 게임에 위험회피자가 19,000원을 내려 한다. 위험프리미엄은?", "ans": 1000.0, "unit": "원", "e": "기대값 20,000원 − 확실성등가 19,000원", "dp": 0, "f": "", "tol": 6.0}, {"k": "calc", "q": "실질이자율 2%, 예상인플레이션 3%일 때 명목이자율(근사식)은?", "ans": 5, "unit": "%", "e": "명목 ≈ 실질 + 예상인플레이션 (피셔 효과)", "dp": 1, "f": "", "tol": 0.050000001}, {"k": "mc", "q": "동시에 최대화할 수 없는 투자의 세 요소는?", "o": ["수익성·유동성·안정성", "규모·속도·비용", "세율·환율·금리", "매출·이익·현금"], "e": ""}, {"k": "mc", "q": "위험이 높은 자산은 실제로 더 높은 수익을 낸다.", "o": ["X (틀리다)", "O (맞다)"], "e": "더 높은 \"기대\"수익을 요구한다는 뜻이지 실현수익을 보장하지 않아요.", "ox": 1}, {"k": "mc", "q": "차익거래 기회가 사라지는 이유는?", "o": ["차익거래 자체가 두 가격을 같게 만들어서", "정부가 금지해서", "수수료가 0이어서", "모든 투자자가 위험을 좋아해서"], "e": ""}, {"k": "mc", "q": "투자 실행과정의 올바른 순서는?", "o": ["자본배분 → 자산배분 → 종목선택", "종목선택 → 자산배분 → 자본배분", "자산배분 → 종목선택 → 자본배분", "종목선택 → 자본배분 → 자산배분"], "e": ""}, {"k": "mc", "q": "소극적(패시브) 관리의 대표 예는?", "o": ["지수를 추종하는 인덱스펀드", "단기 매매로 시장 이기기", "테마주 집중 투자", "신용으로 레버리지 투자"], "e": ""}, {"k": "mc", "q": "원금을 초과하는 손실이 가능한 금융투자상품은?", "o": ["파생상품", "주식", "예금", "국채"], "e": "자본시장법은 원금 초과 손실 가능성으로 증권과 파생상품을 나눠요."}]}, {"id": "iv2", "t": "금융시장과 증권시장", "ic": "市", "d": "증권의 종류, 주가지수, 발행·유통시장", "cards": [{"h": "금융시장의 기능", "p": "돈이 남는 흑자주체에서 모자란 적자주체로 자금을 연결해요. 기능은 <b>자원배분 · 시장감시 · 유동성 제공 · 위험분산</b>이에요. 금융상품은 타인의 미래소득에 대한 청구권이에요."}, {"h": "증권의 분류", "p": "<b>부채증권</b>: 단기 CP·CD, 장기 국채·회사채·ABS / <b>지분증권</b>: 보통주·우선주 / <b>혼합증권(메자닌)</b>: 전환사채 CB, 신주인수권부사채 BW, 교환사채 EB / <b>파생증권</b>: 선도·선물·옵션·스왑"}, {"h": "주식회사와 대리인 문제", "p": "유한책임 · 자본의 증권화 · 소유와 경영의 분리 · 이사회가 특징이에요. 경영자(대리인)가 주주(주인)보다 자기 이익을 앞세우는 <b>대리인 문제</b>를 규율하는 것이 기업지배구조예요."}, {"h": "주가지수", "p": "<b>KOSPI</b>는 1980년 1월 4일 시가총액을 100으로 한 시가총액방식 지수예요. <b>KOSPI200</b>은 1990년 1월 3일 기준(100)이고 지수선물·옵션의 기초자산이에요. 시가총액방식은 대형주 영향이 크고, 다우존스방식(주가평균)은 고가주 영향이 커요."}, {"h": "발행시장과 유통시장", "p": "<b>발행시장</b>(1차)은 새 증권이 처음 팔리는 곳으로 돈이 기업에 들어가요. 사모는 49인 이하 대상, 간접발행은 모집주선·잔액인수·총액인수로 나뉘어요. <b>유통시장</b>(2차)은 투자자끼리 거래하는 곳이라 <b>회사로 돈이 들어가지 않아요.</b>"}], "q": [{"k": "mc", "q": "단기 부채증권에 해당하는 것은?", "o": ["기업어음(CP)", "보통주", "전환사채(CB)", "국채 30년물"], "e": ""}, {"k": "mc", "q": "메자닌(혼합증권)이 아닌 것은?", "o": ["기업어음(CP)", "전환사채(CB)", "신주인수권부사채(BW)", "교환사채(EB)"], "e": ""}, {"k": "mc", "q": "사모 발행의 대상 인원 기준은?", "o": ["49인 이하", "99인 이하", "10인 이하", "제한 없음"], "e": ""}, {"k": "mc", "q": "유통시장에서 주식을 사면 그 돈이 회사로 들어간다.", "o": ["X (틀리다)", "O (맞다)"], "e": "유통시장은 투자자끼리 주식을 사고파는 곳이에요.", "ox": 1}, {"k": "mc", "q": "KOSPI의 기준시점(=100)은?", "o": ["1980년 1월 4일", "1990년 1월 3일", "2000년 1월 4일", "1972년 1월 1일"], "e": "KOSPI200은 1990년 1월 3일 기준이에요."}, {"k": "mc", "q": "시가총액방식 주가지수의 단점은?", "o": ["대형주의 영향력이 크다", "계산이 너무 쉽다", "과거와 비교할 수 없다", "고가주만 반영된다"], "e": "고가주 영향이 큰 건 다우존스(주가평균) 방식이에요."}, {"k": "mc", "q": "인수기관이 발행 증권 전부를 사들인 뒤 투자자에게 파는 방식은?", "o": ["총액인수", "모집주선", "잔액인수", "직접발행"], "e": "잔액인수는 팔고 남은 것만 인수해요."}, {"k": "mc", "q": "대리인 문제의 주인과 대리인은?", "o": ["주주와 경영자", "정부와 기업", "채권자와 은행", "고객과 직원"], "e": ""}, {"k": "mc", "q": "지수선물·지수옵션의 기초자산으로 쓰이는 지수는?", "o": ["KOSPI200", "KOSDAQ", "다우지수", "KRX300만"], "e": ""}]}, {"id": "iv3", "t": "시간가치와 자본비용", "ic": "時", "d": "현재가치, 연금, WACC, CAPM으로 할인율 구하기", "cards": [{"h": "화폐의 시간가치", "p": "같은 금액이라도 지금 받는 게 더 가치 있어요. 소비를 미루는 대가(시간선호)와 무위험이자율 때문이에요.", "f": "FV = PV × (1 + r)ⁿ\nPV = FV ÷ (1 + r)ⁿ", "calc": {"in": [["pv", "현재 금액(원)", 1000000], ["r", "연 이자율(%)", 5], ["n", "기간(년)", 10]], "out": [["미래가치", "pv*Math.pow(1+r/100,n)", "원", 0]]}}, {"h": "할인과 현재가치", "p": "미래 현금흐름을 현재가치로 할인해 비교하면 여러 투자안 중 가장 가치 있는 것을 고를 수 있어요.", "f": "PV = FV ÷ (1 + r)ⁿ", "calc": {"in": [["fv", "미래 금액(원)", 1000000], ["r", "할인율(%)", 8], ["n", "기간(년)", 3]], "out": [["현재가치", "fv/Math.pow(1+r/100,n)", "원", 0]]}}, {"h": "연금과 영구연금", "p": "매기 같은 금액을 받는 연금은 공식으로 한 번에 할인해요. 끝없이 받는 영구연금은 C ÷ r 이에요.", "f": "연금 PV = C × [1 − (1+r)⁻ⁿ] ÷ r\n영구연금 PV = C ÷ r", "calc": {"in": [["c", "매년 받는 금액(원)", 1000000], ["r", "할인율(%)", 10], ["n", "기간(년)", 3]], "out": [["연금의 현재가치", "c*(1-Math.pow(1+r/100,-n))/(r/100)", "원", 0], ["영구연금이라면", "c/(r/100)", "원", 0]]}}, {"h": "자본비용과 WACC", "p": "자본비용은 기업 입장의 최소 필수수익률, 투자자 입장의 최저요구수익률, 가치평가의 할인율이에요. WACC는 <b>시장가치 비중</b>으로 가중하고, 이자는 비용 처리돼 세금을 줄이므로 부채비용은 <b>세후</b>로 넣어요.", "f": "WACC = w_d·K_d·(1−T) + w_e·K_e\nK_e = R_f + β·(R_m − R_f)", "calc": {"in": [["e", "자기자본 시가(억)", 20], ["d", "타인자본 시가(억)", 4.5], ["ke", "자기자본비용(%)", 21], ["kd", "세전 부채비용(%)", 11], ["t", "법인세율(%)", 30]], "out": [["WACC", "(e*ke+d*kd*(1-t/100))/(e+d)", "%", 2]]}}, {"h": "PER의 역수 = 이익수익률", "p": "1/PER = EPS/주가 예요. 강의자료는 이를 기대수익률로 해석하지만, 정확히는 <b>이익수익률</b>이고 실제 기대수익률은 이익의 성장·지속성에 따라 달라져요.", "f": "1 ÷ PER = EPS ÷ 주가", "calc": {"in": [["rf", "무위험이자율(%)", 3], ["b", "베타", 1.2], ["rm", "시장 기대수익률(%)", 8]], "out": [["요구수익률", "rf+b*(rm-rf)", "%", 2], ["시장위험프리미엄", "rm-rf", "%p", 2]]}}], "q": [{"k": "calc", "q": "100만원을 연 5% 복리로 10년 맡기면 미래가치는?", "ans": 1628894.626777, "unit": "원", "e": "FV = 1,000,000 × 1.05¹⁰", "dp": 0, "f": "", "tol": 9773.367760664652}, {"k": "calc", "q": "3년 뒤 받을 100만원의 현재가치는? (할인율 8%)", "ans": 793832.24102, "unit": "원", "e": "PV = 1,000,000 ÷ 1.08³", "dp": 0, "f": "", "tol": 4762.993446121018}, {"k": "calc", "q": "매년 말 100만원을 3년간 받는 연금의 현재가치는? (할인율 10%)", "ans": 2486851.990984, "unit": "원", "e": "연금 PV = C × [1 − 1.1⁻³] ÷ 0.1", "dp": 0, "f": "", "tol": 14921.111945905346}, {"k": "calc", "q": "매년 100만원을 영원히 받는 영구연금의 현재가치는? (할인율 5%)", "ans": 20000000.0, "unit": "원", "e": "C ÷ r", "dp": 0, "f": "", "tol": 120000.0}, {"k": "calc", "q": "[강의 예제 1] 주식 시가 20억, 회사채 시가 4.5억, Ke 21%, 세전 Kd 11%, 법인세 30%일 때 WACC는?", "ans": 18.557143, "unit": "%", "e": "WACC = (20/24.5)×21% + (4.5/24.5)×11%×(1−0.3)", "dp": 2, "f": "", "tol": 0.11134285714285715}, {"k": "calc", "q": "[강의 예제 2] 자기자본 5,800만, 타인자본 2,700만, Rf 4.5%, β 0.9, Rm 13.7%, 세전 Kd 7.15%, 법인세 35%일 때 WACC는?", "ans": 10.196735, "unit": "%", "e": "Ke = 4.5 + 0.9×(13.7−4.5) = 12.78%, 세후 Kd = 4.65%", "dp": 2, "f": "", "tol": 0.061180411764705886}, {"k": "calc", "q": "무위험이자율 3%, 베타 1.2, 시장위험프리미엄 5%일 때 CAPM 자기자본비용은?", "ans": 9.0, "unit": "%", "e": "Ke = Rf + β × MRP", "dp": 2, "f": "", "tol": 0.054}, {"k": "mc", "q": "WACC를 구할 때 비중은 무엇으로 계산하나요?", "o": ["시장가치", "장부가치", "액면가", "취득원가"], "e": ""}, {"k": "mc", "q": "부채비용에 (1−법인세율)을 곱하는 이유는?", "o": ["이자비용이 법인세를 줄여 주기 때문", "부채는 위험이 없기 때문", "배당보다 작기 때문", "회계 규정상 그렇게 정해져 있을 뿐"], "e": ""}, {"k": "calc", "q": "PER이 12.5배인 주식의 이익수익률(1/PER)은?", "ans": 8.0, "unit": "%", "e": "1 ÷ 12.5", "dp": 2, "f": "", "tol": 0.048}]}, {"id": "iv4", "t": "포트폴리오 이론", "ic": "分", "d": "기대수익률·분산, 상관계수와 분산투자 효과", "cards": [{"h": "기대수익률", "p": "상황별 수익률에 확률을 곱해 더해요. 포트폴리오의 기대수익률은 자산별 기대수익률의 <b>가중평균</b>이에요.", "f": "E(R) = Σ pᵢ·Rᵢ\nE(Rₚ) = Σ wᵢ·E(Rᵢ)"}, {"h": "위험의 측정", "p": "실제 수익률이 기대수익률 주변에 얼마나 흩어지는지를 <b>분산·표준편차</b>로 재요. 기대수익률이 같으면 위험이 작은 쪽, 위험이 같으면 기대수익률이 높은 쪽을 고르는 것이 <b>지배원리</b>예요.", "f": "σ² = Σ pᵢ·(Rᵢ − E(R))²"}, {"h": "포트폴리오의 위험", "p": "두 자산을 섞은 위험은 가중평균이 <b>아니에요</b>. 상관계수 ρ가 1보다 작으면 위험이 가중평균보다 작아져요. 강의 예제(A 40%: 20%·30%, B 60%: 15%·10%)에서 ρ = 0.8이면 17.18%, ρ = −0.8이면 8.05%예요.", "f": "σₚ² = w_A²σ_A² + w_B²σ_B² + 2w_Aw_Bσ_Aσ_Bρ", "calc": {"in": [["wa", "A 비중(%)", 40], ["ea", "A 기대수익률(%)", 20], ["sa", "A 표준편차(%)", 30], ["eb", "B 기대수익률(%)", 15], ["sb", "B 표준편차(%)", 10], ["rho", "상관계수", 0.8]], "out": [["포트폴리오 기대수익률", "wa/100*ea+(1-wa/100)*eb", "%", 2], ["포트폴리오 표준편차", "Math.sqrt(Math.pow(wa/100*sa,2)+Math.pow((1-wa/100)*sb,2)+2*(wa/100)*(1-wa/100)*sa*sb*rho)", "%", 2]]}}, {"h": "체계적·비체계적 위험", "p": "종목을 늘리면 <b>비체계적(고유) 위험</b>은 사라지지만 <b>체계적(시장) 위험</b>은 남아요. 이름이 다른 종목이라도 같은 요인(금리·정책·산업)에 묶여 있으면 상관계수가 높아 분산효과가 작아요."}, {"h": "최소분산 포트폴리오", "p": "두 자산으로 위험을 가장 작게 만드는 비중이 있어요. 상관계수가 0이면 분산이 작은 자산에 더 많이 담아요.", "f": "w₁* = (σ₂² − Cov) ÷ (σ₁² + σ₂² − 2Cov)"}], "q": [{"k": "calc", "q": "호황(확률 0.3) 20%, 보통(0.5) 10%, 불황(0.2) −10%일 때 기대수익률은?", "ans": 9.0, "unit": "%", "e": "Σ 확률 × 수익률", "dp": 2, "f": "", "tol": 0.054}, {"k": "calc", "q": "위 주식(기대수익률 9%)의 표준편차는?", "ans": 10.440307, "unit": "%", "e": "σ = √[0.3×11² + 0.5×1² + 0.2×(−19)²]", "dp": 2, "f": "", "tol": 0.06264183905346331}, {"k": "calc", "q": "A에 60만원(기대수익률 10%), B에 40만원(20%) 투자한 포트폴리오의 기대수익률은?", "ans": 14.0, "unit": "%", "e": "가중평균", "dp": 2, "f": "", "tol": 0.084}, {"k": "calc", "q": "[강의 예제] A 비중 0.4(σ 30%), B 0.6(σ 10%), 상관계수 0.8일 때 포트폴리오 표준편차는?", "ans": 17.181385, "unit": "%", "e": "", "dp": 2, "f": "", "tol": 0.10308831165558975}, {"k": "calc", "q": "같은 예제에서 상관계수가 −0.8이면 표준편차는?", "ans": 8.049845, "unit": "%", "e": "", "dp": 2, "f": "", "tol": 0.048299068313995455}, {"k": "calc", "q": "σ₁ = 20%, σ₂ = 30%, 상관계수 0인 두 자산의 최소분산 포트폴리오에서 자산1 비중은?", "ans": 69.230769, "unit": "%", "e": "w₁ = σ₂² ÷ (σ₁² + σ₂²)", "dp": 1, "f": "", "tol": 0.41538461538461535}, {"k": "mc", "q": "두 자산의 상관계수가 −1일 때 가능한 것은?", "o": ["적절한 비중으로 위험을 0으로 만들 수 있다", "분산효과가 전혀 없다", "기대수익률이 0이 된다", "두 자산의 위험이 같아진다"], "e": ""}, {"k": "mc", "q": "종목 수를 충분히 늘리면 체계적 위험도 없앨 수 있다.", "o": ["X (틀리다)", "O (맞다)"], "e": "분산으로 없어지는 건 비체계적(고유) 위험뿐이에요.", "ox": 1}, {"k": "mc", "q": "상관계수가 +1이면?", "o": ["분산효과가 없다(위험은 가중평균)", "위험이 0이 된다", "위험이 커진다", "기대수익률이 높아진다"], "e": ""}, {"k": "mc", "q": "지배원리에 따르면 기대수익률이 같은 두 자산 중 무엇을 고르나요?", "o": ["표준편차가 작은 자산", "표준편차가 큰 자산", "가격이 싼 자산", "아무거나 같다"], "e": ""}]}, {"id": "iv5", "t": "CAPM과 효율적 시장", "ic": "β", "d": "자본배분선, 샤프비율, 베타, SML, 시장효율성", "cards": [{"h": "효용과 위험회피", "p": "평균–분산 효용은 위험이 클수록 깎여요. A는 위험회피계수로, 클수록 위험을 싫어해요.", "f": "U = E(r) − ½·A·σ²", "calc": {"in": [["e", "기대수익률(%)", 12], ["rf", "무위험이자율(%)", 3], ["s", "표준편차(%)", 18], ["A", "위험회피계수 A", 4]], "out": [["샤프비율", "(e-rf)/s", "", 3], ["효용 U = E(r) − ½Aσ²", "(e/100-0.5*A*Math.pow(s/100,2))*100", "%", 2], ["최적 위험자산 비중 y*", "(e-rf)/100/(A*Math.pow(s/100,2))*100", "%", 1]]}}, {"h": "자본배분선과 샤프비율", "p": "무위험자산과 위험자산을 섞으면 직선(CAL)이 생겨요. 기울기가 <b>샤프비율</b>이고, 기울기가 가장 큰 위험포트폴리오가 최적이에요. 그 위에서 각자 위험회피도에 맞게 비중을 정해요.", "f": "Sharpe = (E(r) − r_f) ÷ σ\ny* = (E(r_p) − r_f) ÷ (A·σ_p²)"}, {"h": "CAPM과 베타", "p": "체계적 위험만 보상받으므로 기대수익률은 <b>베타</b>로 정해져요. 베타는 시장이 1% 움직일 때 그 자산이 움직이는 정도예요(β = Cov(i,m) ÷ σ_m²). 이 관계를 그린 직선이 <b>증권시장선(SML)</b>이에요.", "f": "E(rᵢ) = r_f + βᵢ·(E(r_m) − r_f)", "calc": {"in": [["rf", "무위험이자율(%)", 3], ["b", "베타", 1.2], ["rm", "시장 기대수익률(%)", 8]], "out": [["요구수익률", "rf+b*(rm-rf)", "%", 2], ["시장위험프리미엄", "rm-rf", "%p", 2]]}}, {"h": "알파와 성과평가", "p": "CAPM이 말하는 수익보다 더 벌면 양(+)의 알파예요. SML 위에 있는 자산은 저평가, 아래는 고평가예요. 성과지표: <b>샤프</b>(총위험 σ 대비), <b>트레이너</b>(베타 대비), <b>젠센 알파</b>(초과수익).", "f": "α = 실제(기대)수익률 − [r_f + β(r_m − r_f)]"}, {"h": "효율적 시장 가설", "p": "<b>약형</b>: 과거 가격정보 반영 → 기술적 분석 무용 / <b>준강형</b>: 공개정보 모두 반영 → 기본적 분석으로도 초과수익 어려움 / <b>강형</b>: 내부정보까지 반영. 행동재무는 과잉확신·손실회피 같은 편향으로 가격이 벗어날 수 있다고 봐요."}], "q": [{"k": "calc", "q": "기대수익률 12%, 무위험이자율 3%, 표준편차 18%인 포트폴리오의 샤프비율은?", "ans": 0.5, "unit": "", "e": "(12 − 3) ÷ 18", "dp": 2, "f": "", "tol": 0.0050000010000000004}, {"k": "calc", "q": "E(r) = 10%, σ = 20%, A = 4인 투자자의 효용(%)은?", "ans": 2.0, "unit": "%", "e": "U = 0.10 − 0.5 × 4 × 0.2²", "dp": 2, "f": "", "tol": 0.011999999999999995}, {"k": "calc", "q": "위험자산 E(r) = 11%, σ = 20%, 무위험 3%, A = 4일 때 최적 위험자산 비중 y*는?", "ans": 50.0, "unit": "%", "e": "y* = 0.08 ÷ (4 × 0.04)", "dp": 1, "f": "", "tol": 0.29999999999999993}, {"k": "calc", "q": "무위험 3%, 베타 1.5, 시장 기대수익률 9%일 때 CAPM 기대수익률은?", "ans": 12.0, "unit": "%", "e": "", "dp": 2, "f": "", "tol": 0.07200000000000001}, {"k": "calc", "q": "위 주식의 실제 기대수익률이 14%라면 알파는?", "ans": 2.0, "unit": "%p", "e": "14 − 12", "dp": 2, "f": "", "tol": 0.012}, {"k": "mc", "q": "베타가 1.5라는 뜻은?", "o": ["시장이 1% 오를 때 평균 1.5% 움직인다", "연 수익률이 1.5%다", "표준편차가 1.5배다", "배당이 1.5배다"], "e": ""}, {"k": "mc", "q": "SML보다 위에 있는 주식은?", "o": ["저평가(알파 +)", "고평가(알파 −)", "적정가", "무위험자산"], "e": ""}, {"k": "mc", "q": "공개된 정보로는 초과수익을 낼 수 없다는 효율성 형태는?", "o": ["준강형", "약형", "강형", "반강형만 해당 없음"], "e": ""}, {"k": "mc", "q": "트레이너 지수의 분모는?", "o": ["베타", "표준편차", "알파", "무위험이자율"], "e": "샤프는 표준편차, 트레이너는 베타로 나눠요."}, {"k": "mc", "q": "약형 효율적 시장에서는 과거 차트만으로 초과수익을 내기 어렵다.", "o": ["O (맞다)", "X (틀리다)"], "e": "", "ox": 1}]}, {"id": "iv6", "t": "기본적분석과 가치평가", "ic": "價", "d": "자산가치·수익가치·상대가치·법령에 의한 평가", "cards": [{"h": "기본적분석이란", "p": "기업의 내재가치를 구해 시장가격과 비교해요. <b>탑다운</b>은 경제 → 산업 → 기업 순, <b>바텀업</b>은 개별 기업부터 봐요. 재무제표 분석은 '재무제표' 코스에서 자세히 다뤄요."}, {"h": "자산가치", "p": "순자산(자산 − 부채)을 기준으로 봐요. 주당순자산(BPS)과 주가를 비교한 것이 PBR이에요. 청산가치에 가깝지만 무형의 경쟁력은 잘 안 잡혀요.", "f": "BPS = 자기자본 ÷ 발행주식수\nPBR = 주가 ÷ BPS"}, {"h": "수익가치: 배당할인모형", "p": "주식 가치 = 미래 배당의 현재가치. 배당이 일정하게 성장하면 <b>고든 성장모형</b>을 써요. 성장률은 ROE × 유보율(1 − 배당성향)로 추정해요. 성장기회의 현재가치(PVGO)는 성장 없을 때 가치(EPS/k)와의 차이예요.", "f": "P₀ = D₁ ÷ (k − g)\ng = ROE × b", "calc": {"in": [["d1", "내년 배당 D₁(원)", 1000], ["k", "요구수익률(%)", 10], ["g", "배당 성장률(%)", 5]], "out": [["적정 주가", "k>g?d1/((k-g)/100):NaN", "원", 0]]}}, {"h": "상대가치", "p": "비슷한 기업의 배수(PER·PBR·EV/EBITDA)를 곱해 적정가를 구해요. 적정주가 = EPS × 적정 PER.", "f": "적정주가 = EPS × 비교 PER", "calc": {"in": [["p", "주가(원)", 30000], ["eps", "EPS(원)", 2500], ["bps", "BPS(원)", 24000], ["g", "이익 성장률(%)", 10]], "out": [["PER", "p/eps", "배", 2], ["PBR", "p/bps", "배", 2], ["PEG", "p/eps/g", "", 2], ["이익수익률(1/PER)", "eps/p*100", "%", 2]]}}, {"h": "법령에 의한 평가", "p": "비상장주식 같은 시가 없는 주식은 상속세 및 증여세법의 보충적 평가를 써요. 원칙은 1주당 <b>순손익가치와 순자산가치를 3 : 2</b>로 가중평균(부동산 과다 법인은 2 : 3)이에요.", "f": "(순손익가치 × 3 + 순자산가치 × 2) ÷ 5"}], "q": [{"k": "calc", "q": "내년 배당 1,000원, 요구수익률 10%, 성장률 5%일 때 고든 모형 주가는?", "ans": 20000.0, "unit": "원", "e": "D₁ ÷ (k − g)", "dp": 0, "f": "", "tol": 120.0}, {"k": "calc", "q": "ROE 15%, 배당성향 40%일 때 지속가능 성장률은?", "ans": 9.0, "unit": "%", "e": "g = ROE × (1 − 배당성향)", "dp": 1, "f": "", "tol": 0.054}, {"k": "calc", "q": "EPS 3,000원, 적정 PER 12배일 때 적정주가는?", "ans": 36000, "unit": "원", "e": "", "dp": 0, "f": "", "tol": 216.0}, {"k": "calc", "q": "주가 50,000원, BPS 40,000원일 때 PBR은?", "ans": 1.25, "unit": "배", "e": "", "dp": 2, "f": "", "tol": 0.0075}, {"k": "calc", "q": "비상장주식 1주당 순손익가치 30,000원, 순자산가치 20,000원일 때 상증법 평가액(일반 법인)은?", "ans": 26000.0, "unit": "원", "e": "(3 × 순손익가치 + 2 × 순자산가치) ÷ 5", "dp": 0, "f": "", "tol": 156.0}, {"k": "calc", "q": "EPS 2,000원, 요구수익률 10%, 주가 30,000원일 때 PVGO는?", "ans": 10000.0, "unit": "원", "e": "PVGO = 주가 − EPS/k", "dp": 0, "f": "", "tol": 60.0}, {"k": "mc", "q": "탑다운 분석의 순서는?", "o": ["경제 → 산업 → 기업", "기업 → 산업 → 경제", "산업 → 기업 → 경제", "기업만 분석"], "e": ""}, {"k": "mc", "q": "PBR이 1보다 낮으면 무조건 저평가다.", "o": ["X (틀리다)", "O (맞다)"], "e": "자산의 질이 낮거나 ROE가 자본비용보다 낮으면 PBR이 낮은 게 정당할 수 있어요.", "ox": 1}, {"k": "mc", "q": "고든 모형을 쓸 수 없는 경우는?", "o": ["성장률이 요구수익률보다 크거나 같을 때", "배당이 있을 때", "성장률이 0일 때", "요구수익률이 10%일 때"], "e": "k ≤ g이면 분모가 0 이하가 돼요."}]}, {"id": "iv7", "t": "기술적분석", "ic": "線", "d": "추세, 이동평균, 보조지표와 한계", "cards": [{"h": "기술적분석의 가정", "p": "가격에 모든 정보가 반영되고, 가격은 추세를 이루며, 패턴은 반복된다고 봐요. 약형 효율적 시장 가설과 정면으로 부딪히는 접근이라 근거에 대한 논쟁이 계속돼요."}, {"h": "추세선·지지·저항", "p": "저점을 이은 상승 추세선, 매수세가 받쳐 주는 <b>지지선</b>, 매도세가 누르는 <b>저항선</b>을 봐요. 저항선을 뚫으면 지지선으로 바뀌기도 해요."}, {"h": "이동평균선", "p": "일정 기간 종가 평균을 이은 선이에요. 단기선이 장기선을 위로 뚫으면 <b>골든크로스</b>, 아래로 뚫으면 <b>데드크로스</b>예요.", "f": "5일 이동평균 = 최근 5일 종가 합 ÷ 5"}, {"h": "보조지표", "p": "<b>RSI</b>: 70 이상 과매수, 30 이하 과매도 / <b>MACD</b>: 단기·장기 지수이동평균 차이 / <b>볼린저밴드</b>: 이동평균 ± 2표준편차 / <b>거래량</b>: 가격 움직임의 신뢰도를 확인해요."}], "q": [{"k": "calc", "q": "최근 5일 종가가 100, 102, 98, 104, 106일 때 5일 이동평균은?", "ans": 102.0, "unit": "", "e": "", "dp": 1, "f": "", "tol": 0.612}, {"k": "mc", "q": "단기 이동평균선이 장기선을 아래에서 위로 뚫는 것은?", "o": ["골든크로스", "데드크로스", "갭 하락", "헤드앤숄더"], "e": ""}, {"k": "mc", "q": "RSI 75는 일반적으로 어떻게 해석하나요?", "o": ["과매수 구간", "과매도 구간", "중립", "거래 정지"], "e": ""}, {"k": "mc", "q": "볼린저밴드의 구성은?", "o": ["이동평균 ± 2표준편차", "최고가와 최저가", "시가와 종가", "거래량 평균"], "e": ""}, {"k": "mc", "q": "저항선의 의미는?", "o": ["매도세가 몰려 상승이 막히는 가격대", "매수세가 받쳐 주는 가격대", "상한가", "공모가"], "e": ""}, {"k": "mc", "q": "약형 효율적 시장이 성립하면 기술적분석으로 초과수익을 내기 어렵다.", "o": ["O (맞다)", "X (틀리다)"], "e": "", "ox": 1}, {"k": "mc", "q": "거래량을 동반한 가격 상승은 보통 어떻게 해석하나요?", "o": ["상승 추세의 신뢰도가 높다", "곧 하락한다는 신호", "의미 없다", "공매도 증가"], "e": ""}]}, {"id": "iv8", "t": "채권", "ic": "債", "d": "채권 가격, 신용등급, 듀레이션", "cards": [{"h": "채권의 기본", "p": "<b>액면</b>(만기에 받는 원금), <b>표면이자율</b>(쿠폰), <b>만기</b>, <b>만기수익률(YTM)</b>이 핵심이에요. 채권 가격은 미래 이자와 원금을 YTM으로 할인한 값이에요.", "f": "가격 = Σ C ÷ (1+y)ᵗ + F ÷ (1+y)ⁿ", "calc": {"in": [["f", "액면(원)", 10000], ["c", "표면이자율(%)", 5], ["y", "만기수익률(%)", 6], ["n", "만기(년, 연 1회 이자)", 3]], "out": [["채권 가격", "f*(c/100)*(1-Math.pow(1+y/100,-n))/(y/100)+f/Math.pow(1+y/100,n)", "원", 1], ["맥컬리 듀레이션", "(()=>{let p=0,w=0;for(let t=1;t<=n;t++){const cf=f*c/100+(t==n?f:0);const pv=cf/Math.pow(1+y/100,t);p+=pv;w+=t*pv}return w/p})()", "년", 3], ["수정 듀레이션", "(()=>{let p=0,w=0;for(let t=1;t<=n;t++){const cf=f*c/100+(t==n?f:0);const pv=cf/Math.pow(1+y/100,t);p+=pv;w+=t*pv}return w/p/(1+y/100)})()", "", 3]]}}, {"h": "금리와 채권 가격", "p": "시장금리가 오르면 이미 발행된 채권 가격은 <b>내려가요</b>(역관계). 쿠폰이 YTM보다 높으면 할증(액면보다 비쌈), 낮으면 할인 발행돼요."}, {"h": "신용등급", "p": "AAA ~ BBB−는 <b>투자적격</b>, BB+ 이하는 <b>투기등급</b>(하이일드)이에요. 등급이 낮을수록 국채 대비 금리 차이(신용스프레드)가 커요."}, {"h": "듀레이션과 볼록성", "p": "<b>맥컬리 듀레이션</b>은 현금흐름 회수의 가중평균 기간, <b>수정 듀레이션</b> = D ÷ (1+y)는 금리 1%p 변화에 대한 가격 변화율이에요. 무이표채의 듀레이션은 만기와 같고, 쿠폰이 높을수록 듀레이션은 짧아요. 금리 변화가 크면 <b>볼록성</b>이 보정해 줘요.", "f": "가격 변화율 ≈ −D* × Δy (+ ½ × 볼록성 × Δy²)"}, {"h": "수익률곡선", "p": "만기별 금리를 이은 선이에요. 보통 우상향하지만 장기금리가 단기보다 낮아지는 <b>역전</b>은 경기침체 신호로 자주 언급돼요."}], "q": [{"k": "calc", "q": "액면 10,000원, 표면이자율 5%(연 1회), 만기 3년, YTM 6%인 채권 가격은?", "ans": 9732.698805, "unit": "원", "e": "500/1.06 + 500/1.06² + 10,500/1.06³", "dp": 1, "f": "", "tol": 58.396192830323024}, {"k": "calc", "q": "만기 3년 무이표채(액면 10,000원), YTM 5%의 가격은?", "ans": 8638.375985, "unit": "원", "e": "10,000 ÷ 1.05³", "dp": 1, "f": "", "tol": 51.830255911888564}, {"k": "calc", "q": "맥컬리 듀레이션 5년, YTM 4%일 때 수정 듀레이션은?", "ans": 4.807692, "unit": "", "e": "D* = D ÷ (1 + y)", "dp": 2, "f": "", "tol": 0.028846153846153844}, {"k": "calc", "q": "수정 듀레이션 6인 채권, 금리가 0.5%p 오르면 가격 변화율(근사)은?", "ans": -3.0, "unit": "%", "e": "−D* × Δy", "dp": 2, "f": "", "tol": 0.018000000000000002}, {"k": "mc", "q": "시장금리가 오르면 기존 채권 가격은?", "o": ["내려간다", "올라간다", "변하지 않는다", "액면가로 고정된다"], "e": ""}, {"k": "mc", "q": "투자적격 등급의 하한은?", "o": ["BBB−", "A−", "BB+", "B−"], "e": ""}, {"k": "mc", "q": "무이표채의 맥컬리 듀레이션은?", "o": ["만기와 같다", "0이다", "만기보다 길다", "쿠폰에 따라 다르다"], "e": ""}, {"k": "mc", "q": "만기가 같다면 표면이자율이 높은 채권일수록 듀레이션이 짧다.", "o": ["O (맞다)", "X (틀리다)"], "e": "앞쪽 현금흐름 비중이 커지기 때문이에요.", "ox": 1}, {"k": "mc", "q": "장단기 금리차 역전은 주로 무엇의 신호로 언급되나요?", "o": ["경기침체 우려", "물가 급등 확정", "주가 급등", "환율 안정"], "e": ""}]}, {"id": "iv9", "t": "파생상품", "ic": "派", "d": "선물, 옵션, 풋–콜 패리티, 전략", "cards": [{"h": "선도와 선물", "p": "미래에 정한 가격으로 사고팔기로 지금 약속해요. <b>선도</b>는 장외 맞춤 계약, <b>선물</b>은 거래소 표준 계약으로 <b>증거금과 일일정산</b>이 있어요. 배당이 없다면 이론가격은 보유비용만큼 높아요.", "f": "F = S × (1 + r)ᵀ"}, {"h": "옵션", "p": "<b>콜옵션</b>은 살 권리, <b>풋옵션</b>은 팔 권리예요. 매수자는 프리미엄을 내고 권리를 사므로 최대손실이 프리미엄으로 제한돼요. 매도자는 프리미엄을 받는 대신 의무를 져요.", "f": "콜 만기손익 = max(S − K, 0) − 프리미엄\n풋 만기손익 = max(K − S, 0) − 프리미엄", "calc": {"in": [["s", "만기 주가", 120], ["k", "행사가격", 100], ["pc", "콜 프리미엄", 5], ["pp", "풋 프리미엄", 4]], "out": [["콜 매수 손익", "Math.max(s-k,0)-pc", "", 2], ["풋 매수 손익", "Math.max(k-s,0)-pp", "", 2]]}}, {"h": "풋–콜 패리티", "p": "같은 행사가·만기의 유럽형 콜과 풋, 주식, 무위험채권 사이에는 무차익 관계가 있어요. 깨지면 차익거래가 생겨요.", "f": "C + K÷(1+r)ᵀ = P + S", "calc": {"in": [["p", "풋 가격", 5], ["s", "현재 주가", 100], ["k", "행사가격", 100], ["r", "무위험이자율(%)", 5], ["t", "만기(년)", 1]], "out": [["패리티가 말하는 콜 가격", "p+s-k/Math.pow(1+r/100,t)", "", 2]]}}, {"h": "옵션 전략", "p": "<b>보호적 풋</b>: 주식 + 풋 매수(하락 방어) / <b>커버드콜</b>: 주식 + 콜 매도(프리미엄 수입, 상승 제한) / <b>스트래들</b>: 같은 행사가 콜·풋 동시 매수(방향 모를 때 큰 변동에 베팅)"}, {"h": "스왑", "p": "두 당사자가 현금흐름을 교환해요. 대표적으로 고정금리와 변동금리를 바꾸는 <b>금리스왑</b>, 서로 다른 통화를 바꾸는 <b>통화스왑</b>이 있어요."}], "q": [{"k": "calc", "q": "행사가 100, 프리미엄 5인 콜옵션 매수. 만기 주가 120일 때 손익은?", "ans": 15, "unit": "", "e": "max(120 − 100, 0) − 5", "dp": 1, "f": "", "tol": 0.09}, {"k": "calc", "q": "행사가 100, 프리미엄 4인 풋옵션 매수. 만기 주가 90일 때 손익은?", "ans": 6, "unit": "", "e": "", "dp": 1, "f": "", "tol": 0.050000001}, {"k": "calc", "q": "풋 5, 주가 100, 행사가 100, 무위험이자율 5%, 만기 1년일 때 풋–콜 패리티의 콜 가격은?", "ans": 9.761905, "unit": "", "e": "C = P + S − K÷(1+r)", "dp": 2, "f": "", "tol": 0.05857142857142856}, {"k": "calc", "q": "현물 100, 무위험이자율 연 4%, 만기 6개월일 때 선물 이론가격은? (배당 없음)", "ans": 101.98039, "unit": "", "e": "F = S × (1 + r)ᵀ", "dp": 2, "f": "", "tol": 0.6118823416311342}, {"k": "mc", "q": "선물이 선도와 다른 점은?", "o": ["거래소 표준화와 일일정산", "만기가 없다", "옵션처럼 권리만 있다", "현금 결제가 불가능하다"], "e": ""}, {"k": "mc", "q": "보호적 풋의 구성은?", "o": ["주식 보유 + 풋 매수", "주식 보유 + 콜 매도", "콜 매수 + 풋 매도", "주식 공매도 + 콜 매수"], "e": ""}, {"k": "mc", "q": "옵션 매수자의 최대 손실은 지불한 프리미엄이다.", "o": ["O (맞다)", "X (틀리다)"], "e": "", "ox": 1}, {"k": "mc", "q": "주가가 크게 움직일 것 같지만 방향을 모를 때 쓰는 전략은?", "o": ["스트래들 매수", "커버드콜", "보호적 풋", "현물 매수"], "e": ""}, {"k": "mc", "q": "고정금리와 변동금리 이자를 교환하는 계약은?", "o": ["금리스왑", "통화선물", "주가지수옵션", "신용부도스왑만 해당"], "e": ""}]}]}, {"id": "fs", "name": "재무제표", "g": "fs", "d": "재무제표 읽기부터 상대·절대가치 평가, 공시 함정까지", "units": [{"id": "fs1", "t": "재무제표 큰 그림", "ic": "表", "d": "5가지 재무제표와 공시 찾는 법", "cards": [{"h": "재무제표 5종", "p": "<b>재무상태표</b>(특정 시점의 자산·부채·자본), <b>손익계산서</b>(기간 동안의 성과), <b>현금흐름표</b>(기간 동안 현금의 출입), <b>자본변동표</b>, <b>주석</b>이에요. 주석에 우발부채·특수관계자 거래 같은 중요한 내용이 숨어 있어요."}, {"h": "연결과 별도", "p": "<b>연결재무제표</b>는 지배회사와 종속회사를 하나의 경제실체로 합친 것, <b>별도재무제표</b>는 회사 하나만 본 거예요. 지주회사나 자회사가 많은 기업은 연결을 봐야 실체가 보여요. 국내 상장사는 K-IFRS를 따라요."}, {"h": "어디서 보나", "p": "금융감독원 <b>DART</b>(전자공시시스템)에서 사업보고서(연 1회)·반기·분기보고서를 볼 수 있어요. 숫자는 '재무에 관한 사항', 사업 설명은 '사업의 내용'에 있어요."}], "q": [{"k": "mc", "q": "특정 시점의 재무 상태를 보여 주는 표는?", "o": ["재무상태표", "손익계산서", "현금흐름표", "자본변동표"], "e": "손익계산서와 현금흐름표는 '기간'을 보여 줘요."}, {"k": "mc", "q": "지배회사와 종속회사를 합쳐 하나의 실체로 본 재무제표는?", "o": ["연결재무제표", "별도재무제표", "개별 손익계산서", "반기보고서"], "e": ""}, {"k": "mc", "q": "국내 기업 공시를 보는 공식 사이트는?", "o": ["DART(전자공시시스템)", "EDGAR", "한국은행 ECOS", "통계청 KOSIS"], "e": "EDGAR는 미국, ECOS·KOSIS는 경제통계예요."}, {"k": "mc", "q": "주석은 참고용이라 투자 판단에 중요하지 않다.", "o": ["X (틀리다)", "O (맞다)"], "e": "소송·보증·특수관계자 거래 같은 위험이 주석에 있어요.", "ox": 1}, {"k": "mc", "q": "사업보고서는 얼마나 자주 나오나요?", "o": ["연 1회", "매월", "분기마다 사업보고서", "수시로"], "e": "분기·반기에는 분기·반기보고서가 나와요."}]}, {"id": "fs2", "t": "재무상태표", "ic": "資", "d": "자산 = 부채 + 자본, 주요 계정", "cards": [{"h": "기본 등식", "p": "회사가 가진 것(자산)은 남의 돈(부채)과 주주의 돈(자본)으로 마련했어요. 1년 안에 현금이 되거나 갚아야 하면 <b>유동</b>, 아니면 <b>비유동</b>이에요.", "f": "자산 = 부채 + 자본"}, {"h": "주요 자산", "p": "현금및현금성자산, 매출채권(외상 매출), 재고자산, 유형자산(공장·설비), 무형자산(특허·<b>영업권</b>). 영업권은 다른 회사를 장부가보다 비싸게 인수할 때 생긴 웃돈이에요."}, {"h": "부채와 자본", "p": "부채: 매입채무, 차입금, 사채, 충당부채. 자본: 자본금, 자본잉여금, <b>이익잉여금</b>(쌓인 이익), <b>자기주식</b>(회사가 산 자기 주식, 자본에서 차감)."}, {"h": "안정성 지표", "p": "부채비율은 낮을수록, 유동비율은 높을수록 일반적으로 안전하다고 봐요. 단, 업종마다 기준이 달라요.", "f": "부채비율 = 부채 ÷ 자본\n유동비율 = 유동자산 ÷ 유동부채\nBPS = 자본 ÷ 발행주식수"}], "q": [{"k": "calc", "q": "자산 100억, 부채 60억이면 자본은?", "ans": 40, "unit": "억", "e": "자산 − 부채", "dp": 0, "f": "", "tol": 0.500000001}, {"k": "calc", "q": "부채 60억, 자본 40억일 때 부채비율은?", "ans": 150.0, "unit": "%", "e": "", "dp": 0, "f": "", "tol": 0.9}, {"k": "calc", "q": "유동자산 150억, 유동부채 100억일 때 유동비율은?", "ans": 150.0, "unit": "%", "e": "", "dp": 0, "f": "", "tol": 0.9}, {"k": "calc", "q": "자본 40억원, 발행주식수 100만 주일 때 BPS는?", "ans": 4000.0, "unit": "원", "e": "", "dp": 0, "f": "", "tol": 24.0}, {"k": "mc", "q": "자기주식은 재무상태표에서 어떻게 처리되나요?", "o": ["자본에서 차감", "자산으로 계상", "부채로 계상", "수익으로 인식"], "e": ""}, {"k": "mc", "q": "영업권이 생기는 경우는?", "o": ["다른 회사를 순자산보다 비싸게 인수할 때", "광고를 많이 할 때", "특허를 출원할 때", "현금을 쌓을 때"], "e": ""}, {"k": "mc", "q": "이익잉여금이 많으면 그만큼 현금도 많다.", "o": ["X (틀리다)", "O (맞다)"], "e": "이익잉여금은 쌓인 이익의 기록이지 현금이 아니에요. 설비나 재고로 바뀌었을 수 있어요.", "ox": 1}, {"k": "mc", "q": "1년 안에 갚아야 하는 부채는?", "o": ["유동부채", "비유동부채", "자본잉여금", "이연법인세자산"], "e": ""}]}, {"id": "fs3", "t": "손익계산서", "ic": "損", "d": "매출에서 순이익까지, EPS", "cards": [{"h": "이익의 계단", "p": "매출 − 매출원가 = <b>매출총이익</b> → − 판매비와관리비 = <b>영업이익</b>(본업 실력) → ± 영업외손익(이자·외환·처분) = 법인세차감전이익 → − 법인세 = <b>당기순이익</b>."}, {"h": "이익률", "p": "같은 매출이라도 얼마나 남기는지가 중요해요.", "f": "매출총이익률 = 매출총이익 ÷ 매출\n영업이익률 = 영업이익 ÷ 매출\n순이익률 = 순이익 ÷ 매출"}, {"h": "EPS와 일회성 이익", "p": "<b>EPS</b>(주당순이익) = 순이익 ÷ 주식수. 자산 처분이익·환차익 같은 <b>일회성 이익</b>으로 순이익이 튀면 반복되지 않으니 영업이익과 같이 봐야 해요.", "f": "EPS = 당기순이익 ÷ 발행주식수"}], "q": [{"k": "calc", "q": "매출 100억, 매출원가 70억일 때 매출총이익은?", "ans": 30, "unit": "억", "e": "", "dp": 0, "f": "", "tol": 0.500000001}, {"k": "calc", "q": "매출 100억, 영업이익 15억일 때 영업이익률은?", "ans": 15.0, "unit": "%", "e": "", "dp": 1, "f": "", "tol": 0.09}, {"k": "calc", "q": "순이익 50억원, 발행주식수 1,000만 주일 때 EPS는?", "ans": 500.0, "unit": "원", "e": "", "dp": 0, "f": "", "tol": 3.0}, {"k": "calc", "q": "매출 200억, 순이익 12억일 때 순이익률은?", "ans": 6.0, "unit": "%", "e": "", "dp": 1, "f": "", "tol": 0.050000001}, {"k": "mc", "q": "본업에서 번 이익을 보여 주는 항목은?", "o": ["영업이익", "당기순이익", "영업외수익", "법인세비용"], "e": ""}, {"k": "mc", "q": "일회성 이익의 예는?", "o": ["공장 부지 매각 이익", "제품 판매 매출", "매출원가 절감", "판관비 감소"], "e": ""}, {"k": "mc", "q": "매출이 늘면 이익도 반드시 는다.", "o": ["X (틀리다)", "O (맞다)"], "e": "원가·판관비가 더 빨리 늘면 이익은 줄 수 있어요.", "ox": 1}]}, {"id": "fs4", "t": "현금흐름표", "ic": "流", "d": "영업·투자·재무 현금흐름과 FCF", "cards": [{"h": "세 가지 현금흐름", "p": "<b>영업활동</b>: 본업으로 들어온 현금 / <b>투자활동</b>: 설비 투자(유출)·자산 매각(유입) / <b>재무활동</b>: 차입·상환·증자·배당. 배당금 지급은 재무활동이에요."}, {"h": "잉여현금흐름(FCF)", "p": "영업으로 번 현금에서 사업 유지·성장에 필요한 설비투자를 빼고 남는 돈이에요. 배당·자사주·부채상환의 재원이 돼요.", "f": "FCF = 영업활동현금흐름 − 설비투자(CAPEX)"}, {"h": "이익의 질", "p": "순이익은 흑자인데 영업현금흐름이 계속 적자라면 매출채권·재고가 쌓이는 중일 수 있어요. 흑자도산은 이익이 나도 현금이 말라 망하는 경우예요. 건강한 기업은 보통 영업 +, 투자 −, 재무 −(상환·배당) 모양이에요."}], "q": [{"k": "calc", "q": "영업활동현금흐름 120억, 설비투자 80억일 때 FCF는?", "ans": 40, "unit": "억", "e": "", "dp": 0, "f": "", "tol": 0.500000001}, {"k": "mc", "q": "배당금 지급은 어디에 속하나요?", "o": ["재무활동", "영업활동", "투자활동", "포함되지 않음"], "e": ""}, {"k": "mc", "q": "공장 설비 구입은 어디에 속하나요?", "o": ["투자활동", "영업활동", "재무활동", "자본변동"], "e": ""}, {"k": "mc", "q": "순이익은 흑자인데 영업현금흐름이 몇 년째 적자라면?", "o": ["매출채권·재고 증가 등 이익의 질을 의심해 본다", "아주 우량한 신호다", "세금을 안 낸 것이다", "아무 의미 없다"], "e": ""}, {"k": "mc", "q": "영업 +, 투자 −, 재무 − 패턴은 보통 어떤 기업인가요?", "o": ["본업으로 벌어 투자하고 빚을 갚거나 배당하는 기업", "빚으로 버티는 기업", "자산을 팔아 연명하는 기업", "갓 설립한 기업"], "e": ""}, {"k": "mc", "q": "당기순이익이 흑자면 현금은 반드시 늘어난다.", "o": ["X (틀리다)", "O (맞다)"], "e": "", "ox": 1}]}, {"id": "fs5", "t": "재무비율 분석", "ic": "率", "d": "ROE·ROA, 듀퐁 분석, 안정성·활동성", "cards": [{"h": "수익성", "p": "<b>ROE</b>는 주주 돈으로 얼마나 벌었는지, <b>ROA</b>는 전체 자산으로 얼마나 벌었는지예요.", "f": "ROE = 순이익 ÷ 자기자본\nROA = 순이익 ÷ 총자산"}, {"h": "듀퐁 분석", "p": "ROE를 세 조각으로 쪼개면 높은 ROE의 원천이 보여요. 마진이 좋은지, 자산을 빨리 돌리는지, 빚을 많이 쓰는지.", "f": "ROE = 순이익률 × 총자산회전율 × 재무레버리지\n     = (NI/매출) × (매출/자산) × (자산/자본)", "calc": {"in": [["m", "순이익률(%)", 10], ["tu", "총자산회전율(회)", 1.2], ["l", "재무레버리지(자산/자본)", 2]], "out": [["ROE", "m*tu*l", "%", 2]]}}, {"h": "안정성과 활동성", "p": "<b>이자보상배율</b> = 영업이익 ÷ 이자비용, 1 미만이면 번 돈으로 이자도 못 내요. <b>재고자산회전율</b> = 매출원가 ÷ 평균재고, 높을수록 재고가 빨리 팔려요.", "f": "이자보상배율 = 영업이익 ÷ 이자비용\n재고회전율 = 매출원가 ÷ 평균재고"}], "q": [{"k": "calc", "q": "순이익 20억, 자기자본 100억일 때 ROE는?", "ans": 20.0, "unit": "%", "e": "", "dp": 1, "f": "", "tol": 0.12}, {"k": "calc", "q": "순이익률 10%, 총자산회전율 1.2회, 재무레버리지 2배일 때 ROE는?", "ans": 24.0, "unit": "%", "e": "듀퐁: 10% × 1.2 × 2", "dp": 1, "f": "", "tol": 0.14400000000000002}, {"k": "calc", "q": "영업이익 50억, 이자비용 20억일 때 이자보상배율은?", "ans": 2.5, "unit": "배", "e": "", "dp": 2, "f": "", "tol": 0.015}, {"k": "calc", "q": "매출원가 120억, 평균재고 30억일 때 재고자산회전율은?", "ans": 4.0, "unit": "회", "e": "", "dp": 1, "f": "", "tol": 0.050000001}, {"k": "calc", "q": "순이익 30억, 총자산 600억일 때 ROA는?", "ans": 5.0, "unit": "%", "e": "", "dp": 1, "f": "", "tol": 0.050000001}, {"k": "mc", "q": "이자보상배율이 1 미만이라는 뜻은?", "o": ["영업이익으로 이자비용도 못 낸다", "부채가 없다", "이자율이 1% 미만이다", "배당을 많이 한다"], "e": ""}, {"k": "mc", "q": "ROE가 높은데 듀퐁으로 보니 레버리지가 대부분이라면?", "o": ["빚에 기댄 ROE라 위험도 함께 본다", "최고의 우량 기업이다", "마진이 아주 높다", "회전율이 높다"], "e": ""}]}, {"id": "fs6", "t": "상대가치 평가", "ic": "倍", "d": "PER, PBR, EV/EBITDA, PEG", "cards": [{"h": "PER과 PBR", "p": "<b>PER</b> = 주가 ÷ EPS: 이익의 몇 배에 거래되는지. <b>PBR</b> = 주가 ÷ BPS: 순자산의 몇 배인지. PBR = PER × ROE 관계가 있어요.", "f": "PER = 주가 ÷ EPS\nPBR = 주가 ÷ BPS = PER × ROE", "calc": {"in": [["p", "주가(원)", 30000], ["eps", "EPS(원)", 2500], ["bps", "BPS(원)", 24000], ["g", "이익 성장률(%)", 10]], "out": [["PER", "p/eps", "배", 2], ["PBR", "p/bps", "배", 2], ["PEG", "p/eps/g", "", 2], ["이익수익률(1/PER)", "eps/p*100", "%", 2]]}}, {"h": "EV/EBITDA", "p": "<b>EV</b>(기업가치) = 시가총액 + 순차입금. 부채까지 포함한 회사 전체 인수가격이에요. EBITDA는 감가상각 전 영업이익. 부채 구조가 다른 회사끼리 비교할 때 좋아요.", "f": "EV = 시가총액 + 순차입금\nEV/EBITDA = EV ÷ EBITDA"}, {"h": "PEG와 함정", "p": "<b>PEG</b> = PER ÷ 이익성장률(%). 성장이 빠르면 높은 PER도 정당할 수 있어요. 적자 기업은 PER이 의미 없고, 업종이 다르면 배수를 바로 비교할 수 없어요. 은행·지주처럼 자산이 중요한 업종은 PBR을 많이 봐요.", "f": "PEG = PER ÷ EPS 성장률(%)"}], "q": [{"k": "calc", "q": "주가 30,000원, EPS 2,500원일 때 PER은?", "ans": 12.0, "unit": "배", "e": "", "dp": 1, "f": "", "tol": 0.07200000000000001}, {"k": "calc", "q": "시가총액 1,000억, 순차입금 200억, EBITDA 150억일 때 EV/EBITDA는?", "ans": 8.0, "unit": "배", "e": "", "dp": 2, "f": "", "tol": 0.048}, {"k": "calc", "q": "PER 15배, 이익 성장률 10%일 때 PEG는?", "ans": 1.5, "unit": "", "e": "", "dp": 2, "f": "", "tol": 0.009000000000000001}, {"k": "calc", "q": "EPS 4,000원, 업종 평균 PER 10배를 적용한 목표주가는?", "ans": 40000, "unit": "원", "e": "", "dp": 0, "f": "", "tol": 240.0}, {"k": "calc", "q": "PER 8배, ROE 15%인 회사의 PBR은?", "ans": 1.2, "unit": "배", "e": "PBR = PER × ROE", "dp": 2, "f": "", "tol": 0.0072}, {"k": "mc", "q": "PBR을 주로 보는 업종은?", "o": ["은행·지주처럼 자산이 중요한 업종", "적자 바이오", "소프트웨어 스타트업", "게임사"], "e": ""}, {"k": "mc", "q": "적자 기업에 PER이 쓸모없는 이유는?", "o": ["EPS가 음수라 배수가 의미가 없다", "주가가 낮아서", "배당이 없어서", "공시 의무가 없어서"], "e": ""}, {"k": "mc", "q": "PER이 같으면 업종이 달라도 똑같이 싸다고 볼 수 있다.", "o": ["X (틀리다)", "O (맞다)"], "e": "성장률·위험·자본집약도가 달라 업종 간 비교는 조심해야 해요.", "ox": 1}]}, {"id": "fs7", "t": "절대가치 평가", "ic": "DCF", "d": "배당할인모형과 DCF, 터미널가치", "cards": [{"h": "배당할인모형", "p": "주식 가치는 미래 배당의 현재가치예요. 일정하게 성장하면 고든 모형. D₀(올해 배당)가 주어지면 D₁ = D₀ × (1+g)로 바꿔 넣는 걸 잊지 마세요.", "f": "P₀ = D₁ ÷ (k − g),  D₁ = D₀ × (1 + g)", "calc": {"in": [["d1", "내년 배당 D₁(원)", 1000], ["k", "요구수익률(%)", 10], ["g", "배당 성장률(%)", 5]], "out": [["적정 주가", "k>g?d1/((k-g)/100):NaN", "원", 0]]}}, {"h": "DCF", "p": "앞으로 몇 년의 FCF를 예측해 WACC로 할인하고, 그 뒤는 <b>터미널가치</b>로 한 번에 계산해요. 기업가치에서 순차입금을 빼면 주주가치예요.", "f": "기업가치 = Σ FCFₜ ÷ (1+WACC)ᵗ + TV ÷ (1+WACC)ⁿ\nTV = FCFₙ₊₁ ÷ (WACC − g)", "calc": {"in": [["fcf", "내년 FCF(억)", 100], ["w", "WACC(%)", 8], ["g", "영구 성장률(%)", 2]], "out": [["기업가치(영구성장 모형)", "w>g?fcf/((w-g)/100):NaN", "억", 1]]}}, {"h": "민감도와 겸손", "p": "할인율·성장률을 조금만 바꿔도 결과가 크게 바뀌어요. 터미널가치가 전체의 절반 이상인 경우가 많아요. DCF는 정답이 아니라 <b>가정이 맞다면</b>의 가치예요."}], "q": [{"k": "calc", "q": "올해 배당 D₀ 1,000원, 성장률 4%, 요구수익률 9%일 때 주가는?", "ans": 20800.0, "unit": "원", "e": "D₁ = 1,040, P = 1,040 ÷ 0.05", "dp": 0, "f": "", "tol": 124.8}, {"k": "calc", "q": "내년 FCF 100억, WACC 8%, 영구성장률 2%일 때 영구성장 가치는?", "ans": 1666.666667, "unit": "억", "e": "", "dp": 1, "f": "", "tol": 10.0}, {"k": "calc", "q": "1년 뒤 100억, 2년 뒤 110억의 FCF를 10%로 할인한 현재가치 합은?", "ans": 181.818182, "unit": "억", "e": "", "dp": 2, "f": "", "tol": 1.0909090909090908}, {"k": "mc", "q": "할인율(WACC)이 오르면 DCF 가치는?", "o": ["낮아진다", "높아진다", "변하지 않는다", "0이 된다"], "e": ""}, {"k": "mc", "q": "기업가치에서 주주가치를 구하려면?", "o": ["순차입금을 뺀다", "순차입금을 더한다", "배당을 뺀다", "이익을 더한다"], "e": ""}, {"k": "mc", "q": "DCF로 구한 값은 정답 주가다.", "o": ["X (틀리다)", "O (맞다)"], "e": "가정이 맞을 때의 가치일 뿐이에요.", "ox": 1}]}, {"id": "fs8", "t": "공시 읽기와 회계 함정", "ic": "公", "d": "감사의견, 증자·CB 공시, 위험 신호", "cards": [{"h": "감사의견", "p": "<b>적정</b>(문제 없음) · <b>한정</b>(일부 문제) · <b>부적정</b> · <b>의견거절</b>. 부적정·의견거절은 상장폐지 사유가 될 수 있어요. 다만 '적정'은 장부가 규정대로 작성됐다는 뜻이지 좋은 회사라는 보증이 아니에요."}, {"h": "주주에게 중요한 공시", "p": "<b>유상증자</b>: 새 주식 발행으로 지분 희석 / <b>전환사채(CB)</b>: 나중에 주식으로 바뀔 수 있어 잠재 물량(오버행) / <b>자사주 소각</b>: 주식 수 감소로 주당가치 상승 / <b>잠정실적</b>: 컨센서스(시장 예상)보다 좋으면 어닝서프라이즈."}, {"h": "위험 신호", "p": "매출보다 <b>매출채권이 훨씬 빨리 늘거나</b>, 재고가 급증하거나, 영업현금흐름이 계속 적자이거나, 감사인이 자주 바뀌거나, 최대주주가 자주 바뀌면 조심해야 해요."}], "q": [{"k": "mc", "q": "상장폐지 사유가 될 수 있는 감사의견은?", "o": ["의견거절", "적정", "한정만 해당", "감사 생략"], "e": "부적정도 사유가 될 수 있어요."}, {"k": "mc", "q": "감사의견이 '적정'이면 투자하기 좋은 회사다.", "o": ["X (틀리다)", "O (맞다)"], "e": "", "ox": 1}, {"k": "mc", "q": "유상증자가 기존 주주에게 미치는 일반적인 영향은?", "o": ["지분 희석", "배당 증가 확정", "부채 증가", "주식 수 감소"], "e": ""}, {"k": "mc", "q": "전환사채(CB)가 많을 때 걱정하는 '오버행'이란?", "o": ["앞으로 시장에 풀릴 수 있는 잠재 물량", "주가 상한가", "부채비율 하락", "배당 지연"], "e": ""}, {"k": "mc", "q": "매출은 10% 늘었는데 매출채권이 60% 늘었다면?", "o": ["외상 매출 증가로 이익의 질을 점검한다", "영업을 아주 잘한 것이다", "현금이 많이 들어왔다", "재고가 줄었다"], "e": ""}, {"k": "mc", "q": "잠정실적이 컨센서스보다 크게 좋을 때 쓰는 말은?", "o": ["어닝서프라이즈", "어닝쇼크", "가이던스 하향", "윈도드레싱"], "e": ""}]}]}, {"id": "ma", "name": "거시·미시", "g": "ma", "d": "수요·공급, GDP, 물가, 금리, 환율, 무역, 재정", "units": [{"id": "ma1", "t": "미시경제 기초", "ic": "需", "d": "수요·공급, 탄력성, 시장구조", "cards": [{"h": "수요와 공급", "p": "가격이 오르면 수요량은 줄고 공급량은 늘어요. 둘이 만나는 곳이 균형가격이에요. 소득 증가·선호 변화는 수요곡선 자체를 옮겨요(수요 변화)."}, {"h": "가격탄력성", "p": "가격 변화에 수요량이 얼마나 민감한지예요. 1보다 크면 탄력적(사치재), 작으면 비탄력적(필수재). 비탄력적인 제품을 파는 회사는 가격을 올려도 매출이 덜 줄어 <b>가격 결정력</b>이 있어요.", "f": "가격탄력성 = |수요량 변화율 ÷ 가격 변화율|"}, {"h": "시장구조와 해자", "p": "완전경쟁 → 독점적 경쟁 → 과점 → 독점 순으로 기업의 가격 결정력이 커져요. 투자에서는 경쟁자가 따라오기 어려운 강점을 <b>경제적 해자</b>(브랜드, 네트워크 효과, 전환비용, 원가우위)라고 불러요."}, {"h": "기회비용과 한계", "p": "어떤 선택의 비용은 포기한 다른 선택 중 가장 가치 있는 것(<b>기회비용</b>)이에요. 경제학은 '하나 더'의 이득과 비용(<b>한계</b>)으로 판단해요."}], "q": [{"k": "mc", "q": "다른 조건이 같을 때 수요가 늘면 균형가격은?", "o": ["오른다", "내린다", "변하지 않는다", "0이 된다"], "e": ""}, {"k": "calc", "q": "가격이 10% 오르자 수요량이 20% 줄었다. 가격탄력성은?", "ans": 2.0, "unit": "", "e": "|−20% ÷ 10%|", "dp": 1, "f": "", "tol": 0.050000001}, {"k": "mc", "q": "가격탄력성이 낮은 재화의 예는?", "o": ["수도·전기 같은 필수재", "명품 가방", "해외 여행", "고급 외식"], "e": ""}, {"k": "mc", "q": "소수의 기업이 시장을 나누는 구조는?", "o": ["과점", "완전경쟁", "독점적 경쟁", "독점"], "e": ""}, {"k": "mc", "q": "경제적 해자의 예가 아닌 것은?", "o": ["일시적 원자재 가격 하락", "강력한 브랜드", "네트워크 효과", "높은 전환비용"], "e": ""}, {"k": "mc", "q": "독점기업은 가격을 얼마든지 올려도 이익이 계속 는다.", "o": ["X (틀리다)", "O (맞다)"], "e": "가격을 올리면 수요가 줄어 어느 지점부터 이익이 줄어요.", "ox": 1}, {"k": "mc", "q": "기회비용의 뜻은?", "o": ["선택 때문에 포기한 최선의 대안의 가치", "실제로 낸 돈", "세금", "평균 비용"], "e": ""}]}, {"id": "ma2", "t": "GDP와 경기순환", "ic": "GDP", "d": "국내총생산, 실질·명목, 경기 국면", "cards": [{"h": "GDP", "p": "한 나라 안에서 일정 기간 새로 생산된 최종 재화·서비스의 시장가치예요. 지출 측면으로 보면 소비 + 투자 + 정부지출 + 순수출이에요.", "f": "GDP = C + I + G + (X − M)"}, {"h": "명목과 실질", "p": "<b>명목 GDP</b>는 그해 가격, <b>실질 GDP</b>는 기준연도 가격으로 계산해 물가 효과를 뺀 거예요. 경제성장률은 실질 기준이에요. GDP 디플레이터 = 명목 ÷ 실질 × 100.", "f": "실질 성장률 ≈ 명목 성장률 − 물가 상승률"}, {"h": "경기순환", "p": "회복 → 확장 → 후퇴 → 수축을 반복해요. 실제 GDP와 잠재 GDP의 차이가 <b>GDP 갭</b>이에요. 실질 GDP가 2분기 연속 감소하면 관행적으로 '기술적 경기침체'라고 불러요."}, {"h": "경기 선행지표", "p": "앞으로의 경기를 미리 보여 주는 지표예요. 장단기 금리차, 주가지수, 재고순환지표, 건설수주 등이 경기선행지수에 들어가요. 실업률은 경기보다 늦게 움직이는 후행 성격이에요."}], "q": [{"k": "calc", "q": "소비 500, 투자 200, 정부지출 150, 수출 300, 수입 250일 때 GDP는?", "ans": 900, "unit": "조", "e": "C + I + G + X − M", "dp": 0, "f": "", "tol": 5.4}, {"k": "calc", "q": "명목 GDP가 5% 늘고 물가가 2% 올랐다면 실질 성장률(근사)은?", "ans": 3, "unit": "%", "e": "", "dp": 1, "f": "", "tol": 0.050000001}, {"k": "calc", "q": "명목 GDP 2,200조, 실질 GDP 2,000조일 때 GDP 디플레이터는?", "ans": 110.0, "unit": "", "e": "", "dp": 1, "f": "", "tol": 0.6600000000000001}, {"k": "mc", "q": "경제성장률은 보통 무엇을 기준으로 하나요?", "o": ["실질 GDP", "명목 GDP", "GNI", "주가지수"], "e": ""}, {"k": "mc", "q": "관행적인 '기술적 경기침체'의 기준은?", "o": ["실질 GDP 2분기 연속 감소", "주가 20% 하락", "실업률 5% 돌파", "금리 인상 2회"], "e": ""}, {"k": "mc", "q": "경기선행지수에 들어가는 지표의 예는?", "o": ["장단기 금리차", "실업률", "소비자물가 상승률", "법인세 수입"], "e": ""}, {"k": "mc", "q": "GDP가 크면 국민 모두가 부유하다.", "o": ["X (틀리다)", "O (맞다)"], "e": "총량이라 인구·분배를 같이 봐야 해요.", "ox": 1}]}, {"id": "ma3", "t": "물가와 인플레이션", "ic": "物", "d": "CPI, 근원물가, 실질금리, 스태그플레이션", "cards": [{"h": "물가지수", "p": "<b>소비자물가지수(CPI)</b>는 가계가 사는 물건 바구니의 가격 변화예요. 변동이 큰 식료품·에너지를 뺀 것이 <b>근원물가</b>예요. 미국 연준은 PCE 물가도 중요하게 봐요.", "f": "물가상승률 = (올해 지수 ÷ 작년 지수 − 1) × 100"}, {"h": "인플레이션의 원인", "p": "<b>수요견인</b>: 돈이 풀리고 수요가 넘칠 때 / <b>비용인상</b>: 원자재·임금이 오를 때. 물가는 오르는데 경기가 나쁜 상태가 <b>스태그플레이션</b>, 물가가 지속적으로 떨어지는 것은 <b>디플레이션</b>이에요."}, {"h": "실질금리와 돈의 가치", "p": "예금 이자가 물가상승률보다 낮으면 실질적으로 손해예요. 인플레이션은 빚진 사람(채무자)에게 유리하고 현금 보유자에게 불리해요.", "f": "실질금리 ≈ 명목금리 − 물가상승률", "calc": {"in": [["i", "명목금리(%)", 4], ["p", "물가상승률(%)", 3]], "out": [["실질금리(근사)", "i-p", "%", 2], ["실질금리(정확)", "((1+i/100)/(1+p/100)-1)*100", "%", 3]]}}], "q": [{"k": "calc", "q": "소비자물가지수가 105에서 108.15가 되었다. 물가상승률은?", "ans": 3.0, "unit": "%", "e": "", "dp": 2, "f": "", "tol": 0.018000000000000016}, {"k": "calc", "q": "예금금리 4%, 물가상승률 3%일 때 실질금리(근사)는?", "ans": 1, "unit": "%", "e": "", "dp": 1, "f": "", "tol": 0.050000001}, {"k": "calc", "q": "물가가 매년 3%씩 10년 오르면 지금 100만원의 실질 구매력은?", "ans": 744093.914897, "unit": "원", "e": "100만 ÷ 1.03¹⁰", "dp": 0, "f": "", "tol": 4464.56348938035}, {"k": "mc", "q": "근원물가에서 빼는 품목은?", "o": ["식료품과 에너지", "의류와 신발", "주거비", "교육비"], "e": ""}, {"k": "mc", "q": "물가는 오르는데 경기는 침체하는 상태는?", "o": ["스태그플레이션", "디플레이션", "골디락스", "리플레이션"], "e": ""}, {"k": "mc", "q": "예상보다 높은 인플레이션은 보통 누구에게 유리한가요?", "o": ["고정금리 채무자", "고정금리 예금자", "현금 보유자", "연금 생활자"], "e": ""}, {"k": "mc", "q": "물가가 오르면 같은 돈으로 살 수 있는 양이 늘어난다.", "o": ["X (틀리다)", "O (맞다)"], "e": "", "ox": 1}]}, {"id": "ma4", "t": "금리와 통화정책", "ic": "利", "d": "기준금리, 한국은행과 연준, 양적완화", "cards": [{"h": "기준금리", "p": "중앙은행이 정하는 정책금리예요. 한국은행은 <b>금융통화위원회</b>가 연 8회, 미국 연준은 <b>FOMC</b>가 연 8회 회의해요. 한국은행의 목표는 물가안정(+ 금융안정)이에요."}, {"h": "통화정책 수단", "p": "<b>공개시장운영</b>(채권 매매로 돈의 양 조절), 지급준비율, 대출제도. 금리를 더 내릴 수 없을 때 중앙은행이 국채 등을 대량으로 사서 돈을 푸는 것이 <b>양적완화(QE)</b>, 반대로 보유 채권을 줄이는 것이 <b>양적긴축(QT)</b>이에요."}, {"h": "금리가 오르면", "p": "대출이 줄고 소비·투자가 위축돼 물가를 누르고, 기존 채권 가격은 떨어지며, 미래 이익의 현재가치가 줄어 성장주에 부담이 돼요. 해외 자금이 높은 금리를 따라오면 그 나라 통화는 강세 압력을 받아요."}, {"h": "테일러 준칙", "p": "물가와 경기를 보고 적정 기준금리를 가늠하는 경험식이에요.", "f": "i = r* + π + 0.5(π − π*) + 0.5(GDP 갭)"}], "q": [{"k": "mc", "q": "한국은행 기준금리를 결정하는 곳은?", "o": ["금융통화위원회", "기획재정부", "금융감독원", "국회"], "e": ""}, {"k": "mc", "q": "미국 연준의 금리 결정 회의는?", "o": ["FOMC", "ECB", "IMF", "OPEC"], "e": ""}, {"k": "mc", "q": "양적완화(QE)의 내용은?", "o": ["중앙은행이 국채 등을 대량 매입해 돈을 공급", "정부가 세금을 낮춤", "은행이 대출을 줄임", "금리를 올림"], "e": ""}, {"k": "mc", "q": "기준금리 인상의 주된 목적은?", "o": ["물가 안정", "주가 부양", "수출 확대", "실업 증가"], "e": ""}, {"k": "mc", "q": "금리가 오르면 기존 채권 가격은?", "o": ["하락", "상승", "불변", "액면가로 고정"], "e": ""}, {"k": "calc", "q": "균형실질금리 2%, 물가 4%, 목표물가 2%, GDP 갭 +1%일 때 테일러 준칙 금리는?", "ans": 7.5, "unit": "%", "e": "2 + 4 + 0.5×2 + 0.5×1", "dp": 2, "f": "", "tol": 0.045}, {"k": "mc", "q": "금리 인하는 항상 주가를 올린다.", "o": ["X (틀리다)", "O (맞다)"], "e": "경기 악화 때문에 내리는 경우엔 주가가 떨어지기도 해요.", "ox": 1}]}, {"id": "ma5", "t": "환율", "ic": "$₩", "d": "환율 읽기, 결정 요인, 해외투자 수익", "cards": [{"h": "환율 읽는 법", "p": "원/달러 환율 1,300원은 1달러를 사는 데 1,300원이 든다는 뜻이에요. <b>환율 상승 = 원화 약세</b>(달러가 비싸짐), <b>환율 하락 = 원화 강세</b>예요."}, {"h": "환율을 움직이는 것", "p": "두 나라 <b>금리 차</b>(높은 금리 쪽으로 돈이 감), <b>경상수지</b>(흑자면 달러가 들어와 원화 강세), 위험 선호(불안하면 달러 강세), 물가. 장기적으로는 <b>구매력평가(PPP)</b>, 단기 금리 관계는 <b>이자율평가</b>로 설명해요.", "f": "F = S × (1 + i_원) ÷ (1 + i_달러)", "calc": {"in": [["s", "현물환율(원/달러)", 1300], ["ik", "원화 금리(%)", 3], ["iu", "달러 금리(%)", 5], ["t", "기간(년)", 1]], "out": [["이자율평가 선물환율", "s*Math.pow((1+ik/100)/(1+iu/100),t)", "원", 1], ["선물환 할인(−)/할증(+)", "(Math.pow((1+ik/100)/(1+iu/100),t)-1)*100", "%", 2]]}}, {"h": "환율과 기업·투자", "p": "원화 약세는 수출기업 원화 매출을 늘리고, 원자재 수입기업과 해외여행자에게는 불리해요. 해외주식 수익은 <b>현지 주가 수익 × 환율 변화</b>로 결정되고, 환헤지를 하면 환율 영향을 대부분 없애는 대신 비용이 들어요.", "f": "원화 수익률 = (1 + 현지 수익률)(1 + 환율 변동률) − 1", "calc": {"in": [["a", "현지 주가 수익률(%)", 10], ["fx", "환율 변동률(%)", 5]], "out": [["원화 기준 수익률", "((1+a/100)*(1+fx/100)-1)*100", "%", 2]]}}], "q": [{"k": "mc", "q": "원/달러 환율이 1,300원에서 1,400원이 되면?", "o": ["원화 약세", "원화 강세", "달러 약세", "변화 없음"], "e": ""}, {"k": "mc", "q": "원화 약세의 수혜를 보통 받는 쪽은?", "o": ["수출 기업", "원자재 수입 기업", "해외여행자", "달러 부채가 많은 기업"], "e": ""}, {"k": "calc", "q": "미국 주식이 10% 오르고 원/달러 환율이 5% 올랐다. 원화 기준 수익률은?", "ans": 15.5, "unit": "%", "e": "1.10 × 1.05 − 1", "dp": 2, "f": "", "tol": 0.09300000000000015}, {"k": "calc", "q": "현물환율 1,300원, 원화 금리 3%, 달러 금리 5%일 때 1년 선물환율(이자율평가)은?", "ans": 1275.238095, "unit": "원", "e": "1,300 × 1.03 ÷ 1.05", "dp": 1, "f": "", "tol": 7.651428571428571}, {"k": "mc", "q": "빅맥지수가 설명하려는 이론은?", "o": ["구매력평가(PPP)", "이자율평가", "테일러 준칙", "피셔 효과"], "e": ""}, {"k": "mc", "q": "미국 금리가 한국보다 크게 높아지면 일반적으로 원화는?", "o": ["약세 압력", "강세 압력", "영향 없음", "고정"], "e": ""}, {"k": "mc", "q": "경상수지 흑자가 커지면 원화에 강세 압력이 생긴다.", "o": ["O (맞다)", "X (틀리다)"], "e": "달러가 많이 들어오기 때문이에요.", "ox": 1}]}, {"id": "ma6", "t": "국제수지와 무역", "ic": "貿", "d": "경상수지, 무역, 관세, 외환보유액", "cards": [{"h": "국제수지", "p": "<b>경상수지</b> = 상품수지(수출입) + 서비스수지(여행·운송) + 본원소득수지(해외 배당·이자·임금) + 이전소득수지(무상 송금). 돈이 오가는 투자는 <b>금융계정</b>에 기록돼요."}, {"h": "무역과 관세", "p": "관세를 올리면 수입품 가격이 올라 국내 물가가 오르고, 상대국 보복으로 수출이 줄 수 있어요. 수출가격 ÷ 수입가격을 <b>교역조건</b>이라고 해요."}, {"h": "외환보유액", "p": "중앙은행이 가진 외화 자산이에요. 외환위기 때 달러를 공급하고 급격한 환율 변동을 막는 데 써요."}], "q": [{"k": "mc", "q": "해외 주식에서 받은 배당은 어디에 들어가나요?", "o": ["본원소득수지", "상품수지", "서비스수지", "이전소득수지"], "e": ""}, {"k": "mc", "q": "외국인 관광객이 국내에서 쓴 돈은?", "o": ["서비스수지", "상품수지", "본원소득수지", "금융계정"], "e": ""}, {"k": "mc", "q": "수입 관세 인상의 일반적 효과는?", "o": ["수입품 가격 상승", "수입품 가격 하락", "환율 고정", "수출 무조건 증가"], "e": ""}, {"k": "mc", "q": "외환보유액의 주된 역할은?", "o": ["외환위기 대응과 환율 급변 완화", "주식 매수", "세금 징수", "국채 발행"], "e": ""}, {"k": "calc", "q": "수출가격지수 110, 수입가격지수 100일 때 순상품교역조건지수는?", "ans": 110.0, "unit": "", "e": "", "dp": 1, "f": "", "tol": 0.6600000000000001}]}, {"id": "ma7", "t": "재정정책과 경제지표", "ic": "財", "d": "정부지출, 승수, 고용·PMI 읽기", "cards": [{"h": "재정정책", "p": "정부가 지출과 세금으로 경기를 조절해요. 경기가 나쁘면 지출 확대·감세(확장 재정). 다만 정부가 돈을 많이 빌리면 금리가 올라 민간 투자가 줄어드는 <b>구축효과</b>가 생길 수 있어요.", "f": "정부지출 승수 = 1 ÷ (1 − 한계소비성향)", "calc": {"in": [["mpc", "한계소비성향", 0.8], ["g", "정부지출 증가(조)", 10]], "out": [["정부지출 승수", "1/(1-mpc)", "배", 2], ["GDP 증가(단순 모형)", "g/(1-mpc)", "조", 1]]}}, {"h": "뉴스에 자주 나오는 지표", "p": "<b>고용</b>: 실업률, 미국 비농업부문 고용 / <b>물가</b>: CPI, PCE / <b>심리</b>: PMI(50 이상 확장, 미만 위축), 소비자심리지수 / <b>소비</b>: 소매판매. 예상치(컨센서스)와 실제치의 차이에 시장이 반응해요."}], "q": [{"k": "calc", "q": "한계소비성향이 0.8일 때 정부지출 승수는?", "ans": 5.0, "unit": "배", "e": "", "dp": 1, "f": "", "tol": 0.050000001}, {"k": "mc", "q": "구축효과란?", "o": ["정부 차입으로 금리가 올라 민간 투자가 줄어드는 것", "세금이 늘어 소비가 느는 것", "수출이 수입을 밀어내는 것", "물가가 떨어지는 것"], "e": ""}, {"k": "mc", "q": "제조업 PMI 52의 의미는?", "o": ["경기 확장 국면", "경기 위축 국면", "중립", "고용 감소 확정"], "e": ""}, {"k": "mc", "q": "미국 고용시장 대표 지표는?", "o": ["비농업부문 고용", "소매판매", "경상수지", "GDP 디플레이터"], "e": ""}, {"k": "mc", "q": "시장은 지표의 절대 수준보다 예상치와의 차이에 크게 반응한다.", "o": ["O (맞다)", "X (틀리다)"], "e": "", "ox": 1}]}]}, {"id": "nw", "name": "뉴스·실전", "g": "nw", "d": "경제뉴스 용어, 거래 제도, 상품, 세금, 투자 원칙", "units": [{"id": "nw1", "t": "시장 뉴스 용어", "ic": "株", "d": "순매수, 공매도, 서킷브레이커, 약세장", "cards": [{"h": "누가 사고 파나", "p": "<b>외국인·기관·개인</b>의 순매수(산 금액 − 판 금액)가 매일 발표돼요. <b>시가총액</b> = 주가 × 주식 수. <b>블록딜</b>은 장 시작 전·후 대량 지분을 한꺼번에 넘기는 거래로 보통 할인된 가격이라 단기 주가에 부담이에요."}, {"h": "공매도와 숏커버링", "p": "<b>공매도</b>는 빌린 주식을 먼저 팔고 나중에 사서 갚는 거래로, 주가가 내려야 이익이에요. 공매도한 사람이 손실을 막으려고 급히 다시 사는 것이 <b>숏커버링</b>이고, 주가 급등을 부르기도 해요."}, {"h": "안전장치", "p": "국내 주식은 하루 <b>±30%</b> 가격제한폭이 있어요. 지수가 급락하면 <b>서킷브레이커</b>(KOSPI 8%·15%·20% 하락 시 단계별 매매 중단), 선물이 급변하면 <b>사이드카</b>(프로그램매매 5분 정지)가 발동돼요."}, {"h": "시장의 기분", "p": "고점 대비 10% 안팎 하락은 <b>조정</b>, 20% 이상 하락은 관행적으로 <b>약세장(베어마켓)</b>이라 불러요. 상승장은 불마켓. 미국 <b>VIX</b>는 공포지수로, 높을수록 불안이 크다는 뜻이에요."}], "q": [{"k": "mc", "q": "외국인 순매수란?", "o": ["외국인이 산 금액이 판 금액보다 많다", "외국인 보유 비율", "외국인 신규 계좌 수", "외국인 배당 수령액"], "e": ""}, {"k": "mc", "q": "공매도로 이익을 보려면 주가가?", "o": ["내려야 한다", "올라야 한다", "변하지 않아야 한다", "상관없다"], "e": ""}, {"k": "mc", "q": "숏커버링이 주가에 주는 영향은?", "o": ["상승 압력", "하락 압력", "영향 없음", "거래 정지"], "e": ""}, {"k": "mc", "q": "국내 주식의 하루 가격제한폭은?", "o": ["±30%", "±15%", "±10%", "제한 없음"], "e": ""}, {"k": "mc", "q": "지수 급락 시 시장 전체 매매를 일시 중단하는 제도는?", "o": ["서킷브레이커", "사이드카", "VI(변동성완화장치)만", "공매도 금지"], "e": ""}, {"k": "mc", "q": "관행적으로 '약세장'으로 부르는 하락 폭은?", "o": ["고점 대비 20% 이상", "5% 이상", "하루 3% 이상", "50% 이상"], "e": ""}, {"k": "mc", "q": "VIX 지수가 급등했다는 뉴스의 의미는?", "o": ["시장의 불안·공포가 커졌다", "주가가 급등했다", "금리가 내렸다", "거래량이 줄었다"], "e": ""}, {"k": "calc", "q": "주가 50,000원, 발행주식수 2억 주인 회사의 시가총액은?", "ans": 10.0, "unit": "조원", "e": "50,000 × 2억 주", "dp": 1, "f": "", "tol": 0.06}]}, {"id": "nw2", "t": "기업 이벤트 용어", "ic": "社", "d": "증자, 액면분할, 자사주, 배당락, IPO", "cards": [{"h": "주식 수가 바뀌는 이벤트", "p": "<b>유상증자</b>: 돈을 받고 새 주식 발행(희석) / <b>무상증자</b>: 잉여금을 자본금으로 옮겨 공짜로 주식 배분(가치 변화 없음, 권리락) / <b>액면분할</b>: 1주를 여러 주로 쪼갬(가치 변화 없음, 유동성↑)"}, {"h": "주주환원", "p": "<b>자사주 매입</b> 후 <b>소각</b>하면 주식 수가 줄어 주당 가치가 올라요. 소각하지 않고 보유만 하면 나중에 다시 시장에 나올 수 있어요. <b>배당락일</b>에는 배당받을 권리가 사라져 주가가 배당만큼 내려가는 경향이 있어요."}, {"h": "상장과 실적", "p": "<b>IPO</b>는 처음으로 주식을 공개 상장하는 것. 기관이 일정 기간 못 파는 <b>의무보유확약(보호예수)</b>이 풀리면 물량이 나올 수 있어요. <b>가이던스</b>는 회사가 제시하는 실적 전망, <b>어닝쇼크</b>는 예상보다 크게 나쁜 실적이에요."}, {"h": "지배구조 이벤트", "p": "<b>물적분할</b>: 사업부를 자회사로 떼고 모회사가 100% 보유(기존 주주는 새 회사 주식을 직접 못 받음, 자회사 상장 시 가치 희석 논란). <b>인적분할</b>: 기존 주주가 새 회사 주식도 비율대로 받음."}], "q": [{"k": "mc", "q": "기존 주주 지분이 희석되는 이벤트는?", "o": ["유상증자", "액면분할", "자사주 소각", "배당 지급"], "e": ""}, {"k": "calc", "q": "주가 100만원인 주식을 1:10으로 액면분할하면 이론 주가는?", "ans": 100000.0, "unit": "원", "e": "", "dp": 0, "f": "", "tol": 600.0}, {"k": "mc", "q": "자사주 소각의 효과는?", "o": ["주식 수 감소로 주당 가치 상승", "부채 증가", "지분 희석", "배당 금지"], "e": ""}, {"k": "mc", "q": "배당락일에 주가가 내려가는 경향이 있는 이유는?", "o": ["배당받을 권리가 사라져서", "공매도가 늘어서", "세금이 부과돼서", "거래가 정지돼서"], "e": ""}, {"k": "mc", "q": "기존 주주가 새 회사 주식을 직접 받지 못하는 분할은?", "o": ["물적분할", "인적분할", "액면분할", "무상증자"], "e": ""}, {"k": "mc", "q": "어닝쇼크란?", "o": ["실적이 시장 예상보다 크게 나쁨", "실적이 예상보다 크게 좋음", "배당 증가", "상장 폐지"], "e": ""}, {"k": "mc", "q": "무상증자를 하면 회사 가치가 그만큼 늘어난다.", "o": ["X (틀리다)", "O (맞다)"], "e": "자본 안에서 숫자만 옮긴 것이라 기업가치는 그대로예요.", "ox": 1}]}, {"id": "nw3", "t": "거시 뉴스 용어", "ic": "經", "d": "매파·비둘기파, 피벗, 연착륙, 신용스프레드", "cards": [{"h": "중앙은행 말투", "p": "<b>매파</b>(hawk): 물가를 잡으려 금리 인상·긴축 선호 / <b>비둘기파</b>(dove): 경기를 위해 완화 선호 / <b>피벗</b>: 긴축에서 완화로 방향 전환 / <b>테이퍼링</b>: 양적완화 매입 규모를 점차 줄이기 / <b>점도표</b>: FOMC 위원들의 금리 전망"}, {"h": "경기 착륙", "p": "<b>연착륙(소프트랜딩)</b>: 큰 침체 없이 물가가 잡힘 / <b>경착륙</b>: 급격한 침체 / <b>리세션</b>: 경기침체 / <b>골디락스</b>: 성장은 적당하고 물가는 안정된 이상적 상태"}, {"h": "돈과 위험", "p": "<b>유동성</b>: 시장에 풀린 돈, 또는 자산을 바로 현금화할 수 있는 정도 / <b>디레버리징</b>: 빚 줄이기 / <b>신용스프레드</b>: 회사채 금리 − 국채 금리, 벌어지면 신용 위험 우려 / <b>달러인덱스</b>: 주요 6개 통화 대비 달러 가치"}], "q": [{"k": "mc", "q": "금리 인상과 긴축을 선호하는 성향은?", "o": ["매파", "비둘기파", "중립파", "올빼미파"], "e": ""}, {"k": "mc", "q": "'연준이 피벗할 것'이라는 뉴스의 의미는?", "o": ["긴축에서 완화로 방향을 바꿀 것", "금리를 계속 올릴 것", "양적완화를 시작할 것", "금리를 고정할 것"], "e": ""}, {"k": "mc", "q": "테이퍼링이란?", "o": ["양적완화 자산 매입 규모를 점차 줄이기", "금리를 한 번에 크게 올리기", "세금 인하", "채권 발행 확대"], "e": ""}, {"k": "mc", "q": "큰 침체 없이 물가를 잡는 것을 뜻하는 말은?", "o": ["연착륙", "경착륙", "스태그플레이션", "디플레이션"], "e": ""}, {"k": "calc", "q": "회사채 금리 5.2%, 같은 만기 국채 금리 3.5%일 때 신용스프레드는?", "ans": 1.7, "unit": "%p", "e": "", "dp": 1, "f": "", "tol": 0.050000001}, {"k": "mc", "q": "신용스프레드가 크게 벌어지면?", "o": ["기업 신용위험 우려가 커졌다", "경기가 과열됐다", "주가가 오른다", "국채가 부도났다"], "e": ""}, {"k": "mc", "q": "달러인덱스가 오른다는 것은?", "o": ["주요 통화 대비 달러 강세", "달러 약세", "원화 강세만 의미", "미국 금리 하락"], "e": ""}]}, {"id": "nw4", "t": "주문과 거래 제도", "ic": "注", "d": "장 시간, 시장가·지정가, 결제, 반대매매", "cards": [{"h": "거래 시간", "p": "한국거래소 정규장은 <b>09:00 ~ 15:30</b>이에요. 장 시작 전과 마감 직전에는 주문을 모았다가 한 가격으로 체결하는 <b>동시호가</b>가 있어요. 2025년부터는 대체거래소(넥스트레이드)에서 더 긴 시간 거래도 생겼어요."}, {"h": "주문 종류", "p": "<b>지정가</b>: 원하는 가격을 정함(체결 안 될 수 있음) / <b>시장가</b>: 지금 가능한 가격에 즉시 체결(가격이 불리할 수 있음). 주식 대금은 체결일 포함 <b>2영업일 뒤(T+2)</b>에 결제돼요."}, {"h": "빚내서 투자의 위험", "p": "<b>미수</b>: 증거금만 내고 사서 결제일까지 나머지를 내야 하는 거래 / <b>신용거래</b>: 증권사에서 돈을 빌려 매수. 주가가 내려 담보가 부족해지면 증권사가 강제로 파는 <b>반대매매</b>가 일어나요."}], "q": [{"k": "mc", "q": "국내 주식 정규장 시간은?", "o": ["09:00 ~ 15:30", "09:00 ~ 15:00", "10:00 ~ 16:00", "24시간"], "e": ""}, {"k": "mc", "q": "즉시 체결되지만 가격이 불리할 수 있는 주문은?", "o": ["시장가", "지정가", "조건부지정가만", "예약주문"], "e": ""}, {"k": "mc", "q": "월요일에 산 주식의 대금 결제일은? (공휴일 없음)", "o": ["수요일(T+2)", "월요일", "화요일", "금요일"], "e": ""}, {"k": "mc", "q": "담보가 부족해 증권사가 강제로 주식을 파는 것은?", "o": ["반대매매", "공매도", "블록딜", "자사주 매입"], "e": ""}, {"k": "calc", "q": "신용으로 1,000만원어치 주식을 샀고 내 돈은 500만원이다. 주가가 20% 떨어지면 내 돈 기준 손실률은?", "ans": 40.0, "unit": "%", "e": "손실 200만 ÷ 내 돈 500만", "dp": 0, "f": "", "tol": 0.500000001}]}, {"id": "nw5", "t": "투자 상품", "ic": "品", "d": "ETF, ETN, 레버리지, 리츠, TDF", "cards": [{"h": "ETF와 ETN", "p": "<b>ETF</b>는 지수를 따라가는 펀드를 주식처럼 거래소에서 사고파는 상품이에요. <b>ETN</b>은 증권사가 지수 수익을 약속하는 채권 형태라 발행사 신용위험이 있어요. 비용은 <b>총보수</b>, 지수와의 차이는 <b>추적오차</b>예요."}, {"h": "레버리지·인버스", "p": "하루 수익률의 2배, −1배를 따라가요. <b>매일</b> 맞추기 때문에 오르내림을 반복하면 기초지수가 제자리여도 손실이 나요(음의 복리, 변동성 끌림). 단기 도구에 가까워요."}, {"h": "리츠·TDF·채권형", "p": "<b>리츠</b>: 부동산 임대수익을 배당으로 나누는 상장 회사 / <b>TDF</b>: 은퇴 시점에 맞춰 주식 비중을 자동으로 줄이는 펀드 / <b>채권 ETF</b>: 금리가 내리면 가격이 올라요."}], "q": [{"k": "calc", "q": "지수가 하루 +10%, 다음 날 −10%. 2배 레버리지 상품의 2일 누적 수익률은?", "ans": -4.0, "unit": "%", "e": "1.2 × 0.8 − 1 (지수 자체는 −1%)", "dp": 1, "f": "", "tol": 0.050000001}, {"k": "mc", "q": "발행 증권사의 신용위험이 있는 상품은?", "o": ["ETN", "ETF", "예금", "국채"], "e": ""}, {"k": "mc", "q": "지수 수익률과 ETF 수익률의 차이를 부르는 말은?", "o": ["추적오차", "괴리율만", "스프레드", "프리미엄"], "e": ""}, {"k": "mc", "q": "TDF의 특징은?", "o": ["은퇴 시점이 가까워질수록 위험자산 비중을 줄인다", "항상 주식 100%", "하루 2배 수익 추구", "원금 보장"], "e": ""}, {"k": "mc", "q": "리츠의 주된 수익원은?", "o": ["부동산 임대수익 배당", "원자재 시세 차익", "이자 보장", "옵션 프리미엄"], "e": ""}, {"k": "mc", "q": "레버리지 ETF를 오래 들고 있으면 지수 상승률의 정확히 2배를 얻는다.", "o": ["X (틀리다)", "O (맞다)"], "e": "매일 2배를 맞추는 구조라 기간 수익률은 2배와 달라요.", "ox": 1}]}, {"id": "nw6", "t": "세금과 계좌", "ic": "稅", "d": "배당·양도 과세, ISA, 연금계좌 (2026년 기준, 변동 가능)", "cards": [{"h": "배당과 이자", "p": "배당·이자소득은 <b>15.4%</b>(소득세 14% + 지방소득세 1.4%) 원천징수돼요. 연간 금융소득이 <b>2,000만원</b>을 넘으면 넘는 부분이 다른 소득과 합쳐 <b>종합과세</b>돼요."}, {"h": "주식을 팔아 번 돈", "p": "국내 상장주식 매매차익은 <b>대주주</b>(일정 금액 이상 보유자)만 양도세를 내요. 기준은 세법 개정으로 자주 바뀌어요. 해외주식은 연 <b>250만원</b> 공제 후 <b>22%</b>(지방세 포함) 양도세를 다음 해 5월에 신고해요. 2025년 시행 예정이던 금융투자소득세는 2024년 말 폐지가 확정됐어요."}, {"h": "절세 계좌", "p": "<b>ISA</b>: 여러 상품을 한 계좌에 담고 일정 한도 수익까지 비과세, 초과분은 9.9% 분리과세 / <b>연금저축·IRP</b>: 납입액 세액공제, 연금으로 받을 때 낮은 세율. 한도·요건은 해마다 바뀔 수 있으니 가입 전에 금융사·국세청 안내를 확인하세요."}], "q": [{"k": "calc", "q": "배당금 100만원을 받으면 원천징수 후 손에 쥐는 돈은? (15.4%)", "ans": 846000.0, "unit": "원", "e": "", "dp": 0, "f": "", "tol": 5076.0}, {"k": "calc", "q": "해외주식 매매차익 1,250만원(다른 손익 없음)의 양도세는? (250만원 공제, 22%)", "ans": 2200000.0, "unit": "원", "e": "(1,250만 − 250만) × 22%", "dp": 0, "f": "", "tol": 13200.0}, {"k": "mc", "q": "금융소득 종합과세 기준 금액은?", "o": ["연 2,000만원 초과", "연 1,000만원 초과", "연 5,000만원 초과", "기준 없음"], "e": ""}, {"k": "mc", "q": "국내 상장주식 매매차익에 양도세를 내는 사람은?", "o": ["대주주", "모든 투자자", "외국인만", "아무도 안 냄"], "e": ""}, {"k": "mc", "q": "2025년 시행 예정이던 금융투자소득세는?", "o": ["폐지가 확정됐다", "2025년부터 시행됐다", "2030년으로 연기만 됐다", "해외주식에만 적용됐다"], "e": ""}, {"k": "mc", "q": "납입액에 세액공제를 받는 계좌는?", "o": ["연금저축·IRP", "일반 위탁계좌", "CMA", "외화예금"], "e": ""}]}, {"id": "nw7", "t": "투자 원칙과 행동재무", "ic": "心", "d": "분산, 리밸런싱, 적립식, 투자자 편향", "cards": [{"h": "기본 원칙", "p": "<b>분산</b>(상관 낮은 자산 섞기), <b>리밸런싱</b>(정해 둔 비중으로 주기적 복귀 → 오른 걸 팔고 내린 걸 삼), <b>적립식</b>(정기적으로 같은 금액 매수 → 쌀 때 더 많이 사서 평균 매입단가가 단순 평균 주가보다 낮아져요).", "calc": {"in": [["m", "매번 투자금(원)", 100000], ["p1", "1회차 주가", 1000], ["p2", "2회차 주가", 500], ["p3", "3회차 주가", 800]], "out": [["산 주식 수", "m/p1+m/p2+m/p3", "주", 1], ["평균 매입단가", "3*m/(m/p1+m/p2+m/p3)", "원", 1], ["단순 평균 주가", "(p1+p2+p3)/3", "원", 1]]}}, {"h": "복리와 손실의 비대칭", "p": "72 ÷ 수익률 ≈ 원금이 2배가 되는 기간이에요. 50% 손실을 메우려면 100% 수익이 필요해요. 큰 손실을 피하는 게 복리의 핵심이에요.", "f": "2배 기간 ≈ 72 ÷ r\n회복 수익률 = 손실률 ÷ (1 − 손실률)", "calc": {"in": [["r", "연 수익률(%)", 8], ["loss", "손실률(%)", 50]], "out": [["원금 2배까지(72의 법칙)", "72/r", "년", 1], ["원금 2배까지(정확)", "Math.log(2)/Math.log(1+r/100)", "년", 2], ["손실을 메우는 데 필요한 수익률", "loss/(100-loss)*100", "%", 1]]}}, {"h": "투자자의 편향", "p": "<b>손실회피</b>: 손실의 고통이 같은 크기 이익의 기쁨보다 큼 / <b>처분효과</b>: 오른 주식은 빨리 팔고 떨어진 주식은 오래 보유 / <b>확증편향</b>: 보고 싶은 정보만 봄 / <b>과잉확신</b> / <b>군집행동</b>(남 따라 하기) / <b>앵커링</b>(처음 본 가격에 얽매임)"}], "q": [{"k": "calc", "q": "연 8% 수익률이면 원금이 2배가 되는 데 약 몇 년? (72의 법칙)", "ans": 9.0, "unit": "년", "e": "", "dp": 1, "f": "", "tol": 0.054}, {"k": "calc", "q": "50% 손실을 회복하려면 필요한 수익률은?", "ans": 100.0, "unit": "%", "e": "0.5 ÷ 0.5", "dp": 0, "f": "", "tol": 0.6}, {"k": "calc", "q": "매달 10만원씩 주가 1,000원, 500원일 때 두 번 샀다. 평균 매입단가는?", "ans": 666.666667, "unit": "원", "e": "20만원 ÷ 300주", "dp": 1, "f": "", "tol": 4.0}, {"k": "mc", "q": "오른 주식은 빨리 팔고 떨어진 주식은 오래 들고 있는 편향은?", "o": ["처분효과", "확증편향", "앵커링", "군집행동"], "e": ""}, {"k": "mc", "q": "리밸런싱의 효과는?", "o": ["오른 자산을 일부 팔고 내린 자산을 사서 비중 유지", "수익률 보장", "세금 면제", "거래 횟수 0"], "e": ""}, {"k": "mc", "q": "처음 산 가격에 얽매여 판단이 흐려지는 편향은?", "o": ["앵커링", "손실회피", "과잉확신", "최신편향"], "e": ""}, {"k": "mc", "q": "적립식 투자에서 평균 매입단가는 보통 기간 중 단순 평균 주가보다 낮거나 같다.", "o": ["O (맞다)", "X (틀리다)"], "e": "쌀 때 더 많은 주식을 사기 때문이에요(조화평균 ≤ 산술평균).", "ox": 1}]}]}];
